// Chiky Gym · Worker único: sirve la app y guarda los registros en Workers KV.
// Requiere un KV namespace enlazado con el nombre de variable: SYNC
const HTML = "<!doctype html>\n<html lang=\"es\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#ffc8e2\">\n<meta name=\"apple-mobile-web-app-capable\" content=\"yes\">\n<title>Chiky Gym \u00b7 Mi rutina</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Nunito:wght@500;600;700;800&family=Pacifico&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --bg1:#ffe9f4;--bg2:#ffc6e1;--card:#ffffffd9;--card-s:#fff;\n  --ink:#4a1631;--muted:#8d5a74;--line:#f5c3dc;\n  --pink:#e9559b;--pink-d:#c42b78;--pink-l:#ffd9ea;--rose:#fff0f7;\n  --ok:#2fae6b;--warn:#fff3d6;\n  --shadow:0 8px 22px #c42b7822;\n  --nav-h:62px;\n}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml{scroll-padding-top:env(safe-area-inset-top,0px)}\nbody{margin:0;min-height:100vh;color:var(--ink);font:500 16px/1.45 Nunito,system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  background:linear-gradient(170deg,var(--bg1),var(--bg2)) fixed;\n  padding:env(safe-area-inset-top,0px) 0 calc(var(--nav-h) + 92px + env(safe-area-inset-bottom,0px))}\nbutton,input,textarea,select{font:inherit;color:inherit}\nbutton{cursor:pointer}\n:focus-visible{outline:3px solid var(--pink-d);outline-offset:2px}\n.app{max-width:640px;margin:0 auto;padding:14px 14px 0}\nh1,h2,h3,p{margin:0}\n.brand{font-family:Pacifico,\"Brush Script MT\",cursive;font-size:38px;line-height:1.15;color:var(--pink-d);text-shadow:0 2px 0 #fff}\n.sub{color:var(--muted);font-size:14px;font-weight:600}\n.top{display:flex;justify-content:space-between;align-items:center;gap:10px;margin:4px 2px 12px}\n.card{background:var(--card);border:1.5px solid #fff;border-radius:22px;padding:14px;box-shadow:var(--shadow);backdrop-filter:blur(6px)}\n.card+.card,.card+h2,h2+.card{margin-top:12px}\nh2{font-size:18px;font-weight:800;margin:18px 4px 8px}\nh2:first-child{margin-top:4px}\n.av{border-radius:50%;display:block;object-fit:cover;border:3px solid #fff;box-shadow:0 4px 12px #c42b7833;background:var(--pink-l)}\n.avbtn{border:0;background:none;padding:0;border-radius:50%}\n\n.clock{display:flex;align-items:center;gap:14px}\n.clock .t{font-size:44px;font-weight:800;letter-spacing:-1px;line-height:1;font-variant-numeric:tabular-nums;color:var(--pink-d)}\n.clock .d{font-weight:800;font-size:15px;text-transform:capitalize}\n.clock .z{font-size:12px;color:var(--muted);font-weight:700}\n\n.ring{--p:0;width:92px;height:92px;border-radius:50%;flex:none;display:grid;place-items:center;\n  background:conic-gradient(var(--pink) calc(var(--p)*1%),var(--pink-l) 0)}\n.ring b{width:72px;height:72px;border-radius:50%;background:#fff;display:grid;place-items:center;font-size:22px;font-weight:800;color:var(--pink-d)}\n.row{display:flex;gap:12px;align-items:center}\n.grow{flex:1;min-width:0}\n.pill{display:inline-block;border-radius:99px;padding:3px 10px;font-size:12px;font-weight:800;background:var(--pink-l);color:var(--pink-d)}\n.pill.sw2{background:#fff3d6;color:#8a5a00}\n.stats{display:grid;gap:4px;font-size:14px;font-weight:700}\n.stats span{color:var(--muted);font-weight:600}\n\n.btn{border:0;border-radius:16px;padding:13px 16px;font-weight:800;background:linear-gradient(180deg,var(--pink),var(--pink-d));color:#fff;box-shadow:0 6px 14px #c42b7833;width:100%;display:block;text-align:center;text-decoration:none}\n.btn.sec{background:#fff;color:var(--pink-d);border:1.5px solid var(--line);box-shadow:none}\n.btn.sm{width:auto;padding:9px 13px;font-size:14px;border-radius:13px;display:inline-block}\n.link{border:0;background:none;color:var(--pink-d);font-weight:800;font-size:13px;padding:6px 2px;text-decoration:underline;text-underline-offset:3px}\n\n.strip{display:grid;grid-template-columns:repeat(7,1fr);gap:6px;margin-top:10px}\n.strip div{text-align:center;font-size:12px;font-weight:800;color:var(--muted);padding:6px 0;border-radius:14px;background:var(--rose)}\n.strip div i{display:block;font-style:normal;font-size:17px;margin-top:2px;min-height:24px;line-height:24px}\n.strip .today{outline:2.5px solid var(--pink);background:#fff;color:var(--pink-d)}\n.strip .done i{color:var(--ok)}\n\n.chips{display:flex;gap:7px;overflow-x:auto;padding:2px 2px 8px;scrollbar-width:none}\n.chips::-webkit-scrollbar{display:none}\n.chip{border:1.5px solid var(--line);background:#fff;color:var(--muted);border-radius:99px;padding:9px 15px;font-weight:800;white-space:nowrap;flex:none}\n.chip.on{background:var(--pink);border-color:var(--pink);color:#fff}\n.bar{height:9px;border-radius:9px;background:var(--pink-l);overflow:hidden}\n.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--pink),var(--pink-d));border-radius:9px;transition:width .25s}\n\n.note{background:var(--warn);border-radius:16px;padding:11px 13px;font-size:14px;margin-top:12px}\n.note b{color:var(--pink-d)}\n\n.ex{background:var(--card-s);border:1.5px solid var(--line);border-radius:20px;padding:14px;margin-top:10px;box-shadow:var(--shadow)}\n.ex.ok{background:#f1fff7;border-color:#a8e6c4}\n.ex-h{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}\n.ex h3{font-size:16px;font-weight:800;line-height:1.25}\n.ex p{font-size:13.5px;color:var(--muted);margin-top:6px}\n.target{font-weight:800;color:var(--pink-d);font-size:14px;white-space:nowrap}\n.sets{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}\n.set{width:48px;height:48px;border-radius:15px;border:2px solid var(--line);background:var(--rose);font-weight:800;font-size:16px;color:var(--pink-d)}\n.set.on{background:var(--ok);border-color:var(--ok);color:#fff}\n.meta{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-top:12px}\n.kg{display:flex;align-items:center;gap:7px;font-size:13px;font-weight:700;color:var(--muted)}\n.kg input,.fld input,.fld select,.fld textarea{padding:10px 11px;border:1.5px solid var(--line);border-radius:13px;background:var(--rose);font-weight:700;width:100%}\n.kg input{width:84px;text-align:center}\n.prev{font-size:12px;color:var(--muted);font-weight:700}\n.rests{display:flex;gap:5px;align-items:center;flex-wrap:wrap;font-size:12px;color:var(--muted);font-weight:700}\n.rests button{border:1.5px solid var(--line);background:#fff;color:var(--muted);border-radius:10px;padding:6px 8px;font-size:12px;font-weight:800}\n.rests button.on{border-color:var(--pink);color:var(--pink-d);background:var(--pink-l)}\n.acts{display:flex;gap:14px;margin-top:6px;flex-wrap:wrap}\n.win{background:linear-gradient(180deg,#e9fff3,#d4f7e4);border:1.5px solid #a8e6c4;border-radius:20px;padding:14px;margin-top:14px;text-align:center;font-weight:800}\n\n.tbl{overflow-x:auto;margin-top:8px}\ntable{border-collapse:collapse;width:100%;font-size:13px}\nth,td{padding:7px 6px;border-bottom:1px solid var(--line);text-align:center}\nth:first-child,td:first-child{text-align:left;font-weight:700}\nth{color:var(--muted);font-weight:800}\n.chart{width:100%;height:auto;display:block}\n.inl{display:flex;gap:8px;margin-top:10px}\n.inl input{flex:1;min-width:0;padding:11px 12px;border:1.5px solid var(--line);border-radius:14px;background:var(--rose);font-weight:700}\n.kv{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;text-align:center}\n.kv div{background:var(--rose);border-radius:16px;padding:9px 4px}\n.kv b{display:block;font-size:17px;color:var(--pink-d)}\n.kv span{font-size:11.5px;color:var(--muted);font-weight:700}\n.up{color:var(--ok)!important}.dn{color:#b3261e!important}\nul.clean{margin:8px 0 0;padding-left:20px;font-size:14.5px}\nul.clean li{margin:4px 0}\n.fld{display:block;margin-top:10px;font-size:13px;font-weight:800;color:var(--muted)}\n.fld input,.fld select,.fld textarea{margin-top:4px;color:var(--ink)}\n.two{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n\n/* calendario */\n.calh{display:flex;align-items:center;justify-content:space-between;margin-bottom:8px}\n.calh b{font-size:17px;text-transform:capitalize}\n.cal{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}\n.cal .dw{text-align:center;font-size:12px;font-weight:800;color:var(--muted)}\n.cell{aspect-ratio:1;border-radius:14px;border:0;background:var(--rose);display:grid;place-items:center;align-content:center;font-weight:800;font-size:13px;padding:0;color:var(--ink);line-height:1.1}\n.cell i{font-style:normal;font-size:13px;min-height:16px;color:var(--pink)}\n.cell.e{background:none}\n.cell.done{background:#dff7ea}.cell.done i{color:var(--ok);font-weight:800}\n.cell.plan{background:#fff;border:1.5px solid var(--line)}\n.cell.miss i{color:var(--muted)}\n.cell.today{outline:2.5px solid var(--pink-d)}\n.legend{display:flex;gap:12px;flex-wrap:wrap;font-size:12px;font-weight:700;color:var(--muted);margin-top:10px}\n\n/* modal */\n.modal{position:fixed;inset:0;z-index:60;background:#4a163199;display:flex;align-items:flex-end;justify-content:center}\n.modal[hidden]{display:none}\n.sheet{background:#fff8fc;border-radius:26px 26px 0 0;max-width:640px;width:100%;max-height:92vh;overflow:auto;padding:16px 16px calc(22px + env(safe-area-inset-bottom,0px))}\n.sheet h2{margin:0}\n.sheet .x{float:right;border:0;background:var(--pink-l);color:var(--pink-d);width:36px;height:36px;border-radius:50%;font-size:18px;font-weight:800}\n.steps{margin:8px 0 0;padding-left:22px;font-size:15px}\n.steps li{margin:6px 0}\n.opt{display:block;width:100%;text-align:left;border:1.5px solid var(--line);background:#fff;border-radius:16px;padding:12px;margin-top:8px}\n.opt.on{border-color:var(--pink);background:var(--pink-l)}\n.opt b{display:block}\n.opt span{font-size:13px;color:var(--muted);font-weight:600}\n.hist{font-size:13px;margin-top:6px;display:flex;flex-wrap:wrap;gap:6px}\n.hist span{background:var(--rose);border-radius:10px;padding:4px 8px;font-weight:700}\n.sw{width:36px;height:36px;border-radius:50%;border:3px solid #fff;box-shadow:0 0 0 1.5px var(--line);padding:0;flex:none}\n.sw.on{box-shadow:0 0 0 3px var(--pink-d)}\n.toast{position:fixed;left:50%;top:calc(14px + env(safe-area-inset-top,0px));transform:translateX(-50%);z-index:80;background:var(--ink);color:#fff;padding:10px 16px;border-radius:99px;font-weight:800;font-size:14px;box-shadow:0 8px 20px #0003;max-width:90vw;text-align:center}\n.toast[hidden]{display:none}\n\n/* temporizador */\n.timer{position:fixed;left:0;right:0;bottom:calc(var(--nav-h) + env(safe-area-inset-bottom,0px));z-index:20;padding:0 12px 8px}\n.timer-in{max-width:616px;margin:0 auto;background:linear-gradient(180deg,var(--pink),var(--pink-d));color:#fff;border-radius:22px;padding:10px 12px;display:flex;align-items:center;gap:10px;box-shadow:0 10px 26px #c42b7855}\n.timer.run .timer-in{background:linear-gradient(180deg,#d6428c,#a81f64)}\n.tring{--p:0;width:50px;height:50px;border-radius:50%;flex:none;display:grid;place-items:center;background:conic-gradient(#fff calc(var(--p)*1%),#ffffff44 0)}\n.tring b{width:38px;height:38px;border-radius:50%;background:var(--pink-d);display:grid;place-items:center;font-size:11px}\n.tclock{font-size:28px;font-weight:800;font-variant-numeric:tabular-nums;line-height:1}\n.tlab{font-size:12px;opacity:.9;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tbtn{border:0;border-radius:13px;background:#fff;color:var(--pink-d);font-weight:800;padding:10px 12px;font-size:14px}\n.tbtn.g{background:#ffffff33;color:#fff}\n.timer.done .timer-in{animation:pulse .7s 3}\n@keyframes pulse{50%{transform:scale(1.025)}}\n\nnav{position:fixed;left:0;right:0;bottom:0;z-index:30;background:#fffffff0;border-top:1.5px solid var(--line);\n  padding:0 4px env(safe-area-inset-bottom,0px);display:flex;justify-content:center}\nnav .in{display:flex;max-width:640px;width:100%;height:var(--nav-h)}\nnav button{flex:1;border:0;background:none;color:var(--muted);font-size:11px;font-weight:800;display:grid;place-items:center;align-content:center;gap:2px;min-width:0}\nnav button svg{width:24px;height:24px;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}\nnav button.on{color:var(--pink-d)}\n@media(min-width:700px){.app{padding-top:24px}}\n@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\n</style>\n</head>\n<body>\n<div class=\"app\" id=\"app\"></div>\n\n<div class=\"timer\" id=\"timer\">\n  <div class=\"timer-in\">\n    <div class=\"tring\" id=\"tring\"><b>\u23f1</b></div>\n    <div class=\"grow\"><div class=\"tclock\" id=\"tclock\">01:00</div><div class=\"tlab\" id=\"tlab\">Temporizador de descanso</div></div>\n    <button class=\"tbtn g\" id=\"tminus\" aria-label=\"Restar 15 segundos\">\u221215</button>\n    <button class=\"tbtn g\" id=\"tplus\" aria-label=\"Sumar 15 segundos\">+15</button>\n    <button class=\"tbtn\" id=\"tmain\">Iniciar</button>\n  </div>\n</div>\n\n<nav><div class=\"in\" id=\"nav\"></div></nav>\n<div class=\"modal\" id=\"modal\" hidden></div>\n<div class=\"toast\" id=\"toast\" hidden></div>\n\n<script>\n/* ============ DATOS ============ */\nconst TZ = \"America/Bogota\";\nconst DAYS = [\n {n:\"Espalda + b\u00edceps + abdomen\", short:\"Espalda y b\u00edceps\", tag:\"Fuerza y postura\",\n  intro:\"Calienta 8 min en bicicleta suave + 1 serie ligera del primer ejercicio. Pecho abierto, hombros lejos de las orejas.\",\n  ex:[\n   [\"Jal\u00f3n al pecho\",\"Espalda\",3,\"10\u201312\",60,1,\"Lleva la barra a la parte alta del pecho; no te balancees.\"],\n   [\"Remo sentado en polea\",\"Espalda\",3,\"10\u201312\",60,1,\"Pecho abierto, codos hacia atr\u00e1s y esc\u00e1pulas juntas.\"],\n   [\"Remo con mancuerna con mano apoyada en banco\",\"Espalda\",3,\"10\u201312 por lado\",60,0,\"Espalda neutra; el codo viaja hacia la cadera.\"],\n   [\"Face pull en polea\",\"Postura\",3,\"12\u201315\",45,0,\"Tira hacia la cara con codos abiertos; pausa de 1 s.\"],\n   [\"Curl de b\u00edceps con mancuernas\",\"B\u00edceps\",3,\"10\u201312\",45,0,\"Codos pegados al cuerpo, sin impulso.\"],\n   [\"Curl martillo\",\"B\u00edceps\",2,\"12\",45,0,\"Palmas enfrentadas, mu\u00f1ecas neutras.\"],\n   [\"Dead bug\",\"Abdomen\",3,\"8 por lado\",30,0,\"Zona lumbar pegada al suelo mientras alternas brazo y pierna.\"],\n   [\"Pallof press en polea\",\"Abdomen\",3,\"10 por lado\",30,0,\"Empuja al frente sin que el tronco rote.\"],\n   [\"Plancha en antebrazos\",\"Abdomen\",3,\"20\u201340 s\",30,0,\"Cuerpo en l\u00ednea, abdomen firme, gl\u00fateos activos.\"]\n  ]},\n {n:\"Gl\u00fateos + piernas + estabilidad\", short:\"Gl\u00fateos y piernas\", tag:\"Piernas amigables con rodillas\",\n  intro:\"Calienta 8 min en bicicleta + movilidad de cadera. Rango c\u00f3modo: si una rodilla molesta, reduce el recorrido o cambia de ejercicio.\",\n  ex:[\n   [\"Hip thrust en m\u00e1quina o banco\",\"Gl\u00fateos\",3,\"10\u201312\",75,1,\"Sube sin arquear la espalda y pausa 1 s arriba.\"],\n   [\"Peso muerto rumano con mancuernas\",\"Femoral\",3,\"10\",75,1,\"Cadera atr\u00e1s, espalda neutra, rodillas ligeramente flexionadas.\"],\n   [\"Prensa de piernas (rango corto)\",\"Piernas\",3,\"12\",75,0,\"Pies altos en la plataforma y no bajes de unos 70\u00b0 de rodilla.\"],\n   [\"Curl femoral sentado\",\"Femoral\",3,\"12\",60,0,\"Regresa despacio, cadera pegada al asiento.\"],\n   [\"Abducci\u00f3n de cadera en m\u00e1quina\",\"Gl\u00fateos\",3,\"15\",45,0,\"Abre sin rebotes ni impulso.\"],\n   [\"Patada de gl\u00fateo en polea\",\"Gl\u00fateos\",3,\"12 por lado\",45,0,\"Movimiento corto; no arquees la espalda baja.\"],\n   [\"Bird dog\",\"Estabilidad\",3,\"8 por lado\",30,0,\"Pelvis quieta al extender brazo y pierna contrarios.\"],\n   [\"Plancha lateral (rodillas apoyadas)\",\"Estabilidad\",3,\"20\u201330 s por lado\",30,0,\"Hombro, cadera y rodillas alineados.\"]\n  ]},\n {n:\"Espalda + hombros + tr\u00edceps\", short:\"Espalda y hombros\", tag:\"Fuerza y resistencia\",\n  intro:\"Calienta 8 min y haz rotaciones de hombro con banda o sin peso. Prioriza el control de esc\u00e1pulas.\",\n  ex:[\n   [\"Remo con pecho apoyado\",\"Espalda\",3,\"10\u201312\",60,1,\"Pecho apoyado, codos hacia atr\u00e1s sin encoger hombros.\"],\n   [\"Jal\u00f3n agarre neutro\",\"Espalda\",3,\"10\u201312\",60,1,\"Baja los codos hacia las costillas sin echarte atr\u00e1s.\"],\n   [\"P\u00e1jaros en m\u00e1quina (reverse pec deck)\",\"Postura\",3,\"12\u201315\",45,0,\"Poco peso, hombros abajo, abre con control.\"],\n   [\"Press de hombros con mancuernas sentada\",\"Hombros\",3,\"10\",60,0,\"Costillas abajo y abdomen firme; sin arquear.\"],\n   [\"Elevaciones laterales\",\"Hombros\",3,\"12\u201315\",45,0,\"Sube hasta la altura del hombro, sin impulso.\"],\n   [\"Extensi\u00f3n de tr\u00edceps en polea\",\"Tr\u00edceps\",3,\"10\u201312\",45,0,\"Codos pegados al cuerpo.\"],\n   [\"Tr\u00edceps con cuerda sobre la cabeza\",\"Tr\u00edceps\",2,\"12\",45,0,\"Omite si molesta el hombro.\"],\n   [\"Le\u00f1ador en polea (diagonal)\",\"Abdomen\",3,\"10 por lado\",30,0,\"Gira desde el tronco, con brazos casi rectos y abdomen firme.\"]\n  ]},\n {n:\"Brazos + espalda + cardio\", short:\"Brazos y espalda\", tag:\"Resistencia cardiovascular\",\n  intro:\"D\u00eda de volumen moderado. Evita llegar al fallo en todas las series y termina con cardio suave.\",\n  ex:[\n   [\"Remo unilateral en polea\",\"Espalda\",3,\"10 por lado\",60,1,\"Tronco estable, codo hacia la cadera.\"],\n   [\"Pullover en polea\",\"Espalda\",3,\"12\",45,0,\"Brazos casi rectos; siente el dorsal trabajar.\"],\n   [\"Curl de b\u00edceps en polea\",\"B\u00edceps\",3,\"12\",45,0,\"No adelantes los codos.\"],\n   [\"Curl martillo con cuerda\",\"B\u00edceps\",2,\"12\",45,0,\"Mu\u00f1ecas neutras, movimiento controlado.\"],\n   [\"Tr\u00edceps con cuerda\",\"Tr\u00edceps\",3,\"12\",45,0,\"Separa suavemente los extremos al extender.\"],\n   [\"Face pull ligero\",\"Postura\",3,\"15\",30,0,\"Hombros lejos de las orejas al terminar.\"],\n   [\"Crunch inverso en banco\",\"Abdomen\",3,\"12\",30,0,\"Sube la pelvis con control, sin balancear.\"],\n   [\"Cardio: el\u00edptica o bicicleta (ritmo moderado)\",\"Cardio\",1,\"10 min\",0,0,\"Marca la serie al terminar; respiraci\u00f3n c\u00f3moda.\"]\n  ]}\n];\nconst WEEKS = {\n 1:[\"Adaptaci\u00f3n\",\"Aprende la t\u00e9cnica. Deja unas 3 repeticiones en reserva (RIR 3).\"],\n 2:[\"Base\",\"Sube un poco el peso si todo sale f\u00e1cil. Deja unas 2 repeticiones en reserva (RIR 2).\"],\n 3:[\"Progresi\u00f3n\",\"Una serie extra en los ejercicios principales \u2605. Deja 1\u20132 repeticiones en reserva.\"],\n 4:[\"Descarga\",\"Una serie menos y 10\u201315 % menos de peso para recuperar y consolidar.\"]\n};\nconst PLAN_WD = {0:0,1:1,3:2,4:3};\nconst WD_LAB = [\"L\",\"M\",\"X\",\"J\",\"V\",\"S\",\"D\"];\n\n/* Alternativas por molestia (rodilla, cadera u otra) */\nconst ALT = {\n \"Jal\u00f3n al pecho\":[[\"Jal\u00f3n agarre neutro\",\"Palmas enfrentadas: m\u00e1s c\u00f3modo para el hombro.\"],[\"Jal\u00f3n a una mano en polea\",\"Trabaja cada lado por separado con menos carga.\"]],\n \"Remo sentado en polea\":[[\"Remo en m\u00e1quina con pecho apoyado\",\"Sin carga en la zona lumbar ni en la cadera.\"],[\"Remo con banda el\u00e1stica de pie\",\"Menos carga articular y f\u00e1cil de dosificar.\"]],\n \"Remo con mancuerna con mano apoyada en banco\":[[\"Remo inclinado con pecho en banco\",\"Pecho apoyado en un banco inclinado: descarga la espalda baja.\"],[\"Remo en m\u00e1quina con pecho apoyado\",\"Trayectoria guiada y estable.\"]],\n \"Face pull en polea\":[[\"P\u00e1jaros en m\u00e1quina\",\"Misma zona de postura, con el pecho apoyado.\"],[\"Retracci\u00f3n escapular en polea\",\"Tira de los om\u00f3platos hacia atr\u00e1s con brazos casi rectos.\"]],\n \"Curl de b\u00edceps con mancuernas\":[[\"Curl en polea baja\",\"Tensi\u00f3n constante y mejor control.\"],[\"Curl con barra Z\",\"Agarre m\u00e1s c\u00f3modo para las mu\u00f1ecas.\"]],\n \"Curl martillo\":[[\"Curl martillo sentada en banco con respaldo\",\"Sin carga en rodillas ni cadera.\"],[\"Curl martillo con cuerda en polea\",\"Tensi\u00f3n constante y menos balanceo.\"]],\n \"Dead bug\":[[\"Dead bug solo con talones\",\"Mueve solo las piernas para proteger la zona lumbar.\"],[\"Elevaci\u00f3n alterna de pierna tumbada\",\"Espalda baja pegada al suelo, un lado a la vez.\"]],\n \"Pallof press en polea\":[[\"Pallof press sentada en banco\",\"Sin cargar las rodillas.\"],[\"Press isom\u00e9trico con banda\",\"Banda a la altura del pecho; sost\u00e9n 15\u201320 s.\"]],\n \"Plancha en antebrazos\":[[\"Plancha inclinada con manos en banco\",\"Menos carga en hombros y sin apoyar las rodillas.\"],[\"Hollow hold con piernas flexionadas\",\"Tumbada, lumbar pegada; sost\u00e9n 15\u201325 s.\"]],\n \"Hip thrust en m\u00e1quina o banco\":[[\"Puente de gl\u00fateo en suelo\",\"Pies apoyados y rango corto, con o sin mancuerna.\"],[\"Extensi\u00f3n de cadera en m\u00e1quina\",\"Trabaja el gl\u00fateo sin flexionar mucho la rodilla.\"]],\n \"Peso muerto rumano con mancuernas\":[[\"Buenos d\u00edas con banda\",\"Menor carga y control de la bisagra de cadera.\"],[\"Peso muerto rumano en polea baja\",\"M\u00e1s estable y f\u00e1cil de dosificar.\"]],\n \"Prensa de piernas (rango corto)\":[[\"Extensi\u00f3n de cadera en polea\",\"Trabaja gl\u00fateo sin flexi\u00f3n de rodilla.\"],[\"Sentadilla a banco alto con apoyo\",\"Baja muy poco y sube con control.\"]],\n \"Curl femoral sentado\":[[\"Curl femoral tumbada\",\"Posici\u00f3n alternativa si el asiento aprieta la rodilla.\"],[\"Puente con talones apoyados en banco\",\"Isom\u00e9trico de femoral y gl\u00fateo.\"]],\n \"Abducci\u00f3n de cadera en m\u00e1quina\":[[\"Abducci\u00f3n en polea de pie\",\"Con apoyo de mano y rango corto si la cadera molesta.\"],[\"Caminata lateral con banda\",\"Banda sobre las rodillas, pasos cortos.\"]],\n \"Patada de gl\u00fateo en polea\":[[\"Extensi\u00f3n de cadera en m\u00e1quina\",\"Sin apoyar la rodilla.\"],[\"Abducci\u00f3n de cadera tumbada de lado\",\"La pierna superior sube sin rotar la pelvis.\"]],\n \"Bird dog\":[[\"Dead bug\",\"Tumbada, sin apoyar las rodillas.\"],[\"Extensi\u00f3n alterna de pierna boca abajo\",\"Levanta una pierna sin arquear la espalda.\"]],\n \"Plancha lateral (rodillas apoyadas)\":[[\"Plancha lateral con manos en banco\",\"Sin apoyar las rodillas.\"],[\"Inclinaci\u00f3n lateral con mancuerna ligera\",\"De pie, rango corto y control.\"]],\n \"Remo con pecho apoyado\":[[\"Remo sentado en polea\",\"Pecho al frente y espalda neutra.\"],[\"Remo con banda el\u00e1stica\",\"Menos carga articular.\"]],\n \"Jal\u00f3n agarre neutro\":[[\"Jal\u00f3n al pecho\",\"Agarre moderado y recorrido controlado.\"],[\"Jal\u00f3n con banda de pie\",\"Menos carga si hay fatiga o molestia en el hombro.\"]],\n \"P\u00e1jaros en m\u00e1quina (reverse pec deck)\":[[\"Face pull en polea\",\"Misma zona de postura con polea.\"],[\"Aperturas inversas con mancuernas inclinada\",\"Pecho apoyado en banco inclinado.\"]],\n \"Press de hombros con mancuernas sentada\":[[\"Press de hombros en m\u00e1quina\",\"Trayectoria guiada, m\u00e1s estable.\"],[\"Elevaciones frontales alternas sentada\",\"Peso ligero, sin subir los hombros.\"]],\n \"Elevaciones laterales\":[[\"Elevaciones laterales en polea\",\"Tensi\u00f3n constante, menos balanceo.\"],[\"Elevaciones laterales sentada\",\"Evita compensar con las piernas.\"]],\n \"Extensi\u00f3n de tr\u00edceps en polea\":[[\"Extensi\u00f3n de tr\u00edceps con banda\",\"M\u00e1s suave para los codos.\"],[\"Patada de tr\u00edceps con mancuerna\",\"Con apoyo de una mano en el banco.\"]],\n \"Tr\u00edceps con cuerda sobre la cabeza\":[[\"Press franc\u00e9s ligero sentada\",\"Mancuerna ligera y codos estables.\"],[\"Patada de tr\u00edceps con mancuerna\",\"Menos exigencia para el hombro.\"]],\n \"Le\u00f1ador en polea (diagonal)\":[[\"Crunch en m\u00e1quina de abdomen\",\"Sentada y sin apoyar las rodillas.\"],[\"Crunch con piernas elevadas sobre banco\",\"Tumbada, rodillas a 90\u00b0 sobre un banco.\"]],\n \"Remo unilateral en polea\":[[\"Remo sentado en polea\",\"Ambos brazos a la vez, m\u00e1s estable.\"],[\"Remo con mancuerna con mano apoyada en banco\",\"De pie, con la espalda apoyada en la mano.\"]],\n \"Pullover en polea\":[[\"Pullover con mancuerna tumbada en banco\",\"Brazos casi rectos y rango c\u00f3modo.\"],[\"Jal\u00f3n agarre neutro ligero\",\"Alternativa guiada para el dorsal.\"]],\n \"Curl de b\u00edceps en polea\":[[\"Curl con mancuernas sentada\",\"Con respaldo para evitar el impulso.\"],[\"Curl predicador en m\u00e1quina\",\"Codos fijos y trayectoria guiada.\"]],\n \"Curl martillo con cuerda\":[[\"Curl martillo sentada\",\"Sin cargar rodillas ni cadera.\"],[\"Curl con banda el\u00e1stica\",\"Menos carga articular.\"]],\n \"Tr\u00edceps con cuerda\":[[\"Extensi\u00f3n de tr\u00edceps con barra recta en polea\",\"Agarre m\u00e1s estable para las mu\u00f1ecas.\"],[\"Extensi\u00f3n de tr\u00edceps con banda\",\"M\u00e1s suave para los codos.\"]],\n \"Face pull ligero\":[[\"P\u00e1jaros en m\u00e1quina\",\"Pecho apoyado y poco peso.\"],[\"Retracci\u00f3n escapular en polea\",\"Brazos casi rectos y pausa de 1 s.\"]],\n \"Crunch inverso en banco\":[[\"Crunch abdominal en suelo\",\"Cabeza apoyada y movimiento corto.\"],[\"Elevaci\u00f3n de rodillas sentada en banco\",\"Sentada, sin cargar la espalda.\"]],\n \"Cardio: el\u00edptica o bicicleta (ritmo moderado)\":[[\"Caminata inclinada en cinta (suave)\",\"Ritmo c\u00f3modo y sin impacto fuerte.\"],[\"Bicicleta reclinada\",\"Menos carga en la cadera y la espalda baja.\"]]\n};\n/* C\u00f3mo hacerlo: pasos separados por | y error com\u00fan */\nconst HOW = {\n \"Jal\u00f3n al pecho\":[\"Si\u00e9ntate con los muslos fijos bajo el rodillo y agarra la barra un poco m\u00e1s ancha que los hombros.|Baja los codos hacia las costillas y lleva la barra a la parte alta del pecho.|Sube despacio hasta estirar los brazos sin soltar el abdomen.\",\"Echarte hacia atr\u00e1s y tirar con los brazos en vez de con la espalda.\"],\n \"Remo sentado en polea\":[\"Si\u00e9ntate con el pecho alto y las rodillas ligeramente flexionadas.|Tira del agarre hacia el abdomen, codos atr\u00e1s y esc\u00e1pulas juntas.|Regresa con control sin encorvar la espalda.\",\"Balancear el torso para ayudarte.\"],\n \"Remo con mancuerna con mano apoyada en banco\":[\"De pie, apoya una mano en el banco y adelanta la pierna contraria, con la espalda plana.|Tira de la mancuerna hacia la cadera con el codo pegado.|Baja controlando el estiramiento del dorsal.\",\"Rotar el tronco al subir.\"],\n \"Face pull en polea\":[\"Ajusta la polea a la altura de la cara y usa cuerda.|Tira hacia la cara abriendo los codos hacia los lados.|Pausa 1 s y regresa lento.\",\"Usar demasiado peso y encoger los hombros.\"],\n \"Curl de b\u00edceps con mancuernas\":[\"De pie o sentada, mancuernas con palmas al frente y codos pegados.|Sube sin mover los codos hasta contraer el b\u00edceps.|Baja en 2\u20133 s.\",\"Impulsarte con la espalda.\"],\n \"Curl martillo\":[\"Palmas enfrentadas y codos al costado.|Sube las mancuernas con mu\u00f1ecas neutras.|Baja controlando.\",\"Adelantar los codos.\"],\n \"Dead bug\":[\"Tumbada boca arriba, brazos al techo y caderas y rodillas a 90\u00b0.|Baja un brazo y la pierna contraria sin despegar la zona lumbar del suelo.|Vuelve y alterna lados.\",\"Arquear la zona lumbar.\"],\n \"Pallof press en polea\":[\"De pie, de lado a la polea a la altura del pecho, con las manos pegadas al pecho.|Empuja al frente hasta extender los brazos y mant\u00e9n 2 s.|Regresa sin que el tronco gire.\",\"Dejar que la polea te gire.\"],\n \"Plancha en antebrazos\":[\"Codos bajo los hombros y cuerpo en l\u00ednea de cabeza a talones.|Aprieta abdomen y gl\u00fateos.|Respira y sost\u00e9n sin hundir la cadera.\",\"Hundir la cadera o subir los gl\u00fateos.\"],\n \"Hip thrust en m\u00e1quina o banco\":[\"Apoya la espalda alta en el banco con los pies al ancho de caderas.|Empuja con los talones hasta alinear rodillas, cadera y hombros.|Pausa 1 s arriba y baja controlando.\",\"Arquear la espalda baja en lugar de usar el gl\u00fateo.\"],\n \"Peso muerto rumano con mancuernas\":[\"De pie, mancuernas frente a los muslos y rodillas ligeramente flexionadas.|Lleva la cadera atr\u00e1s con la espalda neutra hasta sentir el femoral.|Vuelve empujando la cadera hacia adelante.\",\"Redondear la espalda o flexionar de m\u00e1s las rodillas.\"],\n \"Prensa de piernas (rango corto)\":[\"Pies en la zona media-alta de la plataforma, al ancho de caderas.|Baja hasta unos 70\u00b0 de flexi\u00f3n de rodilla sin despegar la pelvis.|Empuja sin bloquear las rodillas.\",\"Bajar demasiado y despegar la pelvis del respaldo.\"],\n \"Curl femoral sentado\":[\"Ajusta el respaldo y el rodillo sobre los tobillos.|Flexiona llevando los talones bajo el asiento.|Regresa lento.\",\"Levantar la cadera del asiento.\"],\n \"Abducci\u00f3n de cadera en m\u00e1quina\":[\"Espalda apoyada y almohadillas por fuera de las rodillas.|Abre las piernas en 2 s sin impulso.|Cierra despacio.\",\"Usar rebote.\"],\n \"Patada de gl\u00fateo en polea\":[\"Tobillera en la polea baja, suj\u00e9tate al soporte y mant\u00e9n el torso firme.|Lleva la pierna atr\u00e1s con la rodilla casi extendida, solo hasta donde sube el gl\u00fateo.|Regresa sin apoyar la pila de pesas.\",\"Arquear la espalda baja.\"],\n \"Bird dog\":[\"A cuatro apoyos (usa una colchoneta gruesa), mu\u00f1ecas bajo hombros y rodillas bajo caderas.|Extiende brazo y pierna contrarios sin rotar la pelvis y mant\u00e9n 2 s.|Vuelve y alterna.\",\"Rotar la cadera.\"],\n \"Plancha lateral (rodillas apoyadas)\":[\"Apoya el antebrazo bajo el hombro con las rodillas flexionadas.|Sube la cadera hasta alinear hombro, cadera y rodillas.|Sost\u00e9n y respira.\",\"Dejar caer la cadera.\"],\n \"Remo con pecho apoyado\":[\"Ajusta el asiento para que el pecho quede apoyado.|Tira de los agarres llevando los codos atr\u00e1s.|Regresa estirando la espalda sin despegar el pecho.\",\"Encoger los hombros.\"],\n \"Jal\u00f3n agarre neutro\":[\"Agarre con palmas enfrentadas.|Baja los codos hacia las costillas.|Sube controlado.\",\"Inclinarte mucho hacia atr\u00e1s.\"],\n \"P\u00e1jaros en m\u00e1quina (reverse pec deck)\":[\"Pecho contra el respaldo y brazos a la altura del hombro.|Abre los brazos hacia atr\u00e1s con los codos ligeramente flexionados.|Regresa lento.\",\"Subir los hombros.\"],\n \"Press de hombros con mancuernas sentada\":[\"Banco con respaldo y mancuernas a la altura de las orejas.|Empuja hacia arriba sin arquear la espalda.|Baja hasta unos 90\u00b0 de codo.\",\"Arquear la zona lumbar.\"],\n \"Elevaciones laterales\":[\"Mancuernas ligeras a los lados y codos suaves.|Sube hasta la altura de los hombros.|Baja en 2\u20133 s.\",\"Balancear el cuerpo.\"],\n \"Extensi\u00f3n de tr\u00edceps en polea\":[\"Codos pegados al cuerpo y agarre a la altura del pecho.|Extiende hacia abajo sin mover los codos.|Sube hasta unos 90\u00b0.\",\"Separar los codos.\"],\n \"Tr\u00edceps con cuerda sobre la cabeza\":[\"De espaldas a la polea, cuerda detr\u00e1s de la cabeza y un pie adelante.|Extiende los brazos al frente y arriba.|Regresa con los codos estables.\",\"Arquear la espalda.\"],\n \"Le\u00f1ador en polea (diagonal)\":[\"De pie, de lado a la polea alta, agarre con ambas manos.|Baja en diagonal hacia la cadera contraria girando el tronco, brazos casi rectos.|Regresa controlando con el abdomen firme.\",\"Usar los brazos en lugar del tronco.\"],\n \"Remo unilateral en polea\":[\"De pie o sentada, agarre de una mano a la altura del pecho.|Tira llevando el codo hacia la cadera.|Regresa sin rotar el tronco.\",\"Rotar el torso.\"],\n \"Pullover en polea\":[\"De pie frente a la polea alta con los brazos casi rectos.|Lleva la barra hacia los muslos con los brazos rectos.|Sube sintiendo el estiramiento del dorsal.\",\"Flexionar los codos.\"],\n \"Curl de b\u00edceps en polea\":[\"Polea baja con barra recta o Z.|Sube sin mover los codos.|Baja lento.\",\"Impulsarte con el tronco.\"],\n \"Curl martillo con cuerda\":[\"Polea baja con cuerda y palmas enfrentadas.|Sube hacia los hombros.|Baja controlado.\",\"Adelantar los codos.\"],\n \"Tr\u00edceps con cuerda\":[\"Polea alta con cuerda y codos al costado.|Extiende y separa los extremos al final.|Sube lento.\",\"Inclinarte sobre la polea.\"],\n \"Face pull ligero\":[\"Polea a la altura de la cara con cuerda y poco peso.|Tira hacia la cara abriendo los codos.|Termina con los hombros lejos de las orejas.\",\"Usar demasiado peso.\"],\n \"Crunch inverso en banco\":[\"Tumbada y sujetando el banco con las manos, rodillas flexionadas.|Sube la pelvis llevando las rodillas hacia el pecho.|Baja sin balancear.\",\"Usar impulso.\"],\n \"Cardio: el\u00edptica o bicicleta (ritmo moderado)\":[\"Calienta 2 min y elige una intensidad en la que puedas hablar con frases cortas.|Mant\u00e9n 10 min.|Baja el ritmo el \u00faltimo minuto.\",\"Ir demasiado fuerte.\"]\n};\nconst REG = {Espalda:[\"back\"],Postura:[\"back\",\"shoulder\"],\"B\u00edceps\":[\"biceps\"],\"Tr\u00edceps\":[\"triceps\"],Hombros:[\"shoulder\"],Abdomen:[\"abs\"],\"Gl\u00fateos\":[\"glutes\"],Femoral:[\"hams\"],Piernas:[\"quads\",\"glutes\",\"hams\"],Estabilidad:[\"abs\",\"glutes\"],Cardio:[\"quads\",\"hams\"]};\nconst ZONES = {\n rodilla:\"Con molestia de rodilla: reduce el recorrido, baja el peso y evita flexionar m\u00e1s de 70\u201390\u00b0. Si el dolor contin\u00faa, deja el ejercicio.\",\n cadera:\"Con molestia de cadera: usa rango corto, evita rotaciones forzadas y prefiere apoyos estables.\",\n otra:\"Con otra molestia: baja el peso y elige la variante m\u00e1s guiada y estable.\"\n};\nconst SKIN=[\"#f7d3b8\",\"#e8b48f\",\"#c68a63\",\"#8d5a3c\"];\nconst HAIR=[\"#3b2216\",\"#1f1612\",\"#a2521f\",\"#d9a441\",\"#c42b78\"];\nconst BAND=[\"#e9559b\",\"#a974e8\",\"#3aa6d9\",\"#2fae6b\"];\nconst STYLES=[\"Rizos\",\"Cola\",\"Mo\u00f1o\",\"Suelto\"];\n\n/* ============ ESTADO ============ */\nconst KEY = \"chikyGymV1\";\nlet state = {view:\"home\",day:0,week:1,start:null,done:{},kg:{},rest:{},log:{},body:[],\n  hist:{},swap:{},past:[],cnt:{},auto:true,calMonth:null,progTab:\"gen\",\n  profile:{name:\"Chiky\",age:40,cm:159,kg0:56.8,goal:\"Mejorar postura, abdomen y espalda\",level:\"Intermedia\",limits:\"Molestias de rodillas (algunas veces)\",material:\"Gimnasio completo\"},\n  avatar:{mode:\"svg\",skin:1,hair:0,style:0,band:0,photo:null},rev:0};\nconst DEF=JSON.parse(JSON.stringify({profile:state.profile,avatar:state.avatar}));\nfunction load(){\n  try{const o=JSON.parse(localStorage.getItem(KEY));\n    if(o&&typeof o===\"object\"){state={...state,...o,profile:{...state.profile,...(o.profile||{})},avatar:{...state.avatar,...(o.avatar||{})}}}}catch(e){}\n}\nconst SYNC_FIELDS=[\"start\",\"done\",\"kg\",\"rest\",\"log\",\"body\",\"hist\",\"swap\",\"past\",\"cnt\",\"auto\",\"profile\",\"avatar\"];\nconst snapshot=()=>{const o={};SYNC_FIELDS.forEach(k=>o[k]=state[k]);return o};\nvar lastFp=null,sync=null;\nfunction save(){\n  try{const fp=JSON.stringify(snapshot());\n    if(lastFp===null)lastFp=fp;\n    else if(fp!==lastFp){lastFp=fp;state.rev=Date.now();schedulePush()}}catch(e){}\n  try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){toast(\"No se pudo guardar: el navegador est\u00e1 lleno o bloqueado.\")}\n}\nload();\n\n/* ============ FECHAS (Colombia) ============ */\nfunction bogota(){\n  const d=new Date();\n  const f=(o,l=\"es-CO\")=>new Intl.DateTimeFormat(l,{timeZone:TZ,...o}).format(d);\n  const wk=f({weekday:\"short\"},\"en-US\");\n  return {iso:f({},\"en-CA\"),\n    date:f({weekday:\"long\",day:\"numeric\",month:\"long\",year:\"numeric\"}),\n    time:f({hour:\"2-digit\",minute:\"2-digit\",hourCycle:\"h23\"}),\n    wd:[\"Mon\",\"Tue\",\"Wed\",\"Thu\",\"Fri\",\"Sat\",\"Sun\"].indexOf(wk)};\n}\nconst dayMs=864e5;\nconst toUTC=iso=>Date.parse(iso+\"T00:00:00Z\");\nconst addDays=(iso,n)=>new Date(toUTC(iso)+n*dayMs).toISOString().slice(0,10);\nconst wdOf=iso=>(new Date(toUTC(iso)).getUTCDay()+6)%7;\nfunction mondayOf(iso){return addDays(iso,-wdOf(iso))}\nfunction weekOf(iso){return Math.floor((toUTC(iso)-toUTC(state.start))/(7*dayMs))+1}\nconst pad=n=>String(n).padStart(2,\"0\");\nfunction monthLabel(ym){const [y,m]=ym.split(\"-\").map(Number);return new Intl.DateTimeFormat(\"es-CO\",{timeZone:\"UTC\",month:\"long\",year:\"numeric\"}).format(new Date(Date.UTC(y,m-1,1)))}\nfunction addMonth(ym,n){const [y,m]=ym.split(\"-\").map(Number);const d=new Date(Date.UTC(y,m-1+n,1));return `${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}`}\nfunction shortDate(iso){return new Intl.DateTimeFormat(\"es-CO\",{timeZone:\"UTC\",day:\"numeric\",month:\"short\"}).format(new Date(toUTC(iso)))}\nif(!state.start){state.start=mondayOf(bogota().iso);state.week=1;save()}\nfunction currentWeek(){return Math.min(4,Math.max(1,weekOf(bogota().iso)))}\nif(!state.weekInit){state.week=currentWeek();state.weekInit=true;save()}\nif(lastFp===null)lastFp=JSON.stringify(snapshot());\n\n/* ============ L\u00d3GICA ============ */\nconst $=id=>document.getElementById(id);\nconst esc=s=>String(s).replace(/[&<>\"']/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\",\"'\":\"&#39;\"}[c]));\nconst kx=(w,d,e)=>`${w}-${d}-${e}`;\nconst P=()=>state.profile;\nfunction setsFor(ex,w){\n  const b=ex[2];\n  if(b===1)return 1;\n  if(w===3&&ex[5])return b+1;\n  if(w===4)return Math.max(2,b-1);\n  return b;\n}\nfunction exInfo(d,i){\n  const ex=DAYS[d].ex[i],sw=state.swap[`${d}-${i}`];\n  const alt=(sw!==undefined&&ALT[ex[0]]&&ALT[ex[0]][sw])?ALT[ex[0]][sw]:null;\n  return {d,i,base:ex[0],name:alt?alt[0]:ex[0],tip:alt?alt[1]:ex[6],how:alt?null:HOW[ex[0]],group:ex[1],sets:ex[2],reps:ex[3],rest:ex[4],main:ex[5],alt:!!alt};\n}\nfunction lookup(name){\n  for(let d=0;d<DAYS.length;d++)for(let i=0;i<DAYS[d].ex.length;i++){\n    const ex=DAYS[d].ex[i];\n    if(ex[0]===name)return {d,i,base:name,name,tip:ex[6],how:HOW[name],group:ex[1],sets:ex[2],reps:ex[3],rest:ex[4],main:ex[5],alt:false};\n    const a=(ALT[ex[0]]||[]).find(x=>x[0]===name);\n    if(a)return {d,i,base:ex[0],name,tip:a[1],how:null,group:ex[1],sets:ex[2],reps:ex[3],rest:ex[4],main:ex[5],alt:true};\n  }\n  return null;\n}\nfunction dayProgress(w,d){\n  let t=0,c=0;\n  DAYS[d].ex.forEach((ex,i)=>{const s=setsFor(ex,w);t+=s;c+=Math.min(s,+state.done[kx(w,d,i)]||0)});\n  return {t,c,p:t?Math.round(c/t*100):0};\n}\nfunction weekProgress(w){let t=0,c=0;DAYS.forEach((_,d)=>{const x=dayProgress(w,d);t+=x.t;c+=x.c});return {t,c,p:t?Math.round(c/t*100):0}}\nfunction planProgress(){let t=0,c=0;[1,2,3,4].forEach(w=>{const x=weekProgress(w);t+=x.t;c+=x.c});return {t,c,p:t?Math.round(c/t*100):0}}\nfunction sessionsDone(w){return DAYS.filter((_,d)=>state.log[`${w}-${d}`]).length}\nfunction syncLog(w,d){\n  const k=`${w}-${d}`,{t,c}=dayProgress(w,d);\n  if(t&&c>=t){if(!state.log[k])state.log[k]=bogota().iso}else delete state.log[k];\n}\nfunction sessionsList(){\n  const cur=Object.entries(state.log).map(([k,date])=>{const [w,d]=k.split(\"-\").map(Number);return {date,day:d,week:w}});\n  return [...state.past,...cur];\n}\nfunction bodySorted(){return [...state.body].sort((a,b)=>a.date<b.date?-1:1)}\nfunction lastBody(){const b=bodySorted();return b.length?b[b.length-1].kg:P().kg0}\nconst imc=()=>(lastBody()/Math.pow(P().cm/100,2)).toFixed(1);\n\n/* historial de pesos por ejercicio */\nfunction setHist(name,w,val){\n  const iso=bogota().iso;let a=(state.hist[name]||[]).filter(e=>e.d!==iso);\n  const v=parseFloat(val);if(v>0)a.push({d:iso,kg:v,w});\n  a.sort((x,y)=>x.d<y.d?-1:1);\n  if(a.length)state.hist[name]=a;else delete state.hist[name];\n}\nfunction prevHist(name,w){\n  const a=(state.hist[name]||[]).filter(e=>e.w<w);\n  return a.length?a[a.length-1]:null;\n}\nfunction pctChange(name){const a=state.hist[name]||[];if(a.length<2)return null;return (a[a.length-1].kg/a[0].kg-1)*100}\nfunction strengthTotal(){\n  const v=Object.keys(state.hist).map(pctChange).filter(x=>x!==null);\n  return v.length?v.reduce((a,b)=>a+b,0)/v.length:null;\n}\nfunction strengthMonth(ym){\n  const v=[];\n  Object.keys(state.hist).forEach(n=>{\n    const a=state.hist[n],m=a.filter(e=>e.d.startsWith(ym));\n    if(m.length&&a.length>1)v.push((Math.max(...m.map(e=>e.kg))/a[0].kg-1)*100);\n  });\n  return v.length?v.reduce((a,b)=>a+b,0)/v.length:null;\n}\nconst fmtPct=p=>p===null?\"\u2013\":`${p>0?\"+\":\"\"}${p.toFixed(0)} %`;\nconst cls=p=>p===null||Math.abs(p)<.5?\"\":(p>0?\"up\":\"dn\");\n\nfunction nextWorkout(){\n  const now=bogota();\n  for(let o=0;o<=14;o++){\n    const iso=addDays(now.iso,o),wd=wdOf(iso);\n    if(!(wd in PLAN_WD))continue;\n    const w=weekOf(iso);if(w<1||w>4)continue;\n    const d=PLAN_WD[wd];\n    if(!state.log[`${w}-${d}`])return {o,w,d,iso};\n  }\n  return null;\n}\nfunction relDay(o,iso){\n  if(o===0)return \"Hoy\";if(o===1)return \"Ma\u00f1ana\";\n  const n=new Intl.DateTimeFormat(\"es-CO\",{timeZone:\"UTC\",weekday:\"long\"}).format(new Date(toUTC(iso)));\n  return n.charAt(0).toUpperCase()+n.slice(1);\n}\nlet toastT=null;\nfunction toast(m){const t=$(\"toast\");t.textContent=m;t.hidden=false;clearTimeout(toastT);toastT=setTimeout(()=>t.hidden=true,2400)}\n\n/* ============ TEMPORIZADOR ============ */\nconst T={total:60,end:0,left:60,run:false,iv:null,ctx:null,label:\"\"};\nfunction beep(){\n  try{\n    T.ctx=T.ctx||new (window.AudioContext||window.webkitAudioContext)();\n    [0,.22,.44].forEach(t=>{\n      const o=T.ctx.createOscillator(),g=T.ctx.createGain();\n      o.frequency.value=t>.4?1040:780;o.connect(g);g.connect(T.ctx.destination);\n      g.gain.setValueAtTime(.18,T.ctx.currentTime+t);g.gain.exponentialRampToValueAtTime(.001,T.ctx.currentTime+t+.18);\n      o.start(T.ctx.currentTime+t);o.stop(T.ctx.currentTime+t+.2);\n    });\n  }catch(e){}\n  try{navigator.vibrate&&navigator.vibrate([250,120,250])}catch(e){}\n}\nconst mmss=s=>`${pad(Math.floor(s/60))}:${pad(s%60)}`;\nfunction drawTimer(){\n  $(\"tclock\").textContent=mmss(Math.max(0,T.left));\n  $(\"tring\").style.setProperty(\"--p\",T.total?(T.left/T.total*100):0);\n  $(\"tmain\").textContent=T.run?\"Pausa\":(T.left<T.total&&T.left>0?\"Seguir\":\"Iniciar\");\n  $(\"tlab\").textContent=T.run?`Descansando${T.label?\" \u00b7 \"+T.label:\"\"}`:(T.left===0?\"\u00a1Listo, siguiente serie!\":\"Temporizador de descanso\");\n  $(\"timer\").classList.toggle(\"run\",T.run);\n}\nfunction tick(){\n  T.left=Math.max(0,Math.ceil((T.end-Date.now())/1000));drawTimer();\n  if(T.left<=0){\n    clearInterval(T.iv);T.run=false;drawTimer();beep();\n    const el=$(\"timer\");el.classList.remove(\"done\");void el.offsetWidth;el.classList.add(\"done\");\n  }\n}\nfunction startTimer(sec,label){\n  clearInterval(T.iv);T.label=label||\"\";T.total=sec;T.left=sec;T.end=Date.now()+sec*1000;T.run=true;\n  T.iv=setInterval(tick,250);drawTimer();\n  try{T.ctx=T.ctx||new (window.AudioContext||window.webkitAudioContext)()}catch(e){}\n}\nfunction pauseTimer(){clearInterval(T.iv);T.run=false;drawTimer()}\nfunction resumeTimer(){T.end=Date.now()+T.left*1000;T.run=true;clearInterval(T.iv);T.iv=setInterval(tick,250);drawTimer()}\nfunction adjustTimer(d){\n  T.left=Math.max(0,T.left+d);if(T.left>T.total)T.total=T.left;\n  if(T.run)T.end=Date.now()+T.left*1000;\n  drawTimer();\n}\n$(\"tmain\").onclick=()=>{\n  if(T.run)pauseTimer();\n  else if(T.left>0&&T.left<T.total)resumeTimer();\n  else startTimer(T.total||60,T.label);\n};\n$(\"tplus\").onclick=()=>adjustTimer(15);\n$(\"tminus\").onclick=()=>adjustTimer(-15);\ndocument.addEventListener(\"visibilitychange\",()=>{if(!document.hidden&&T.run)tick()});\n\n/* ============ GR\u00c1FICOS Y AVATAR ============ */\nfunction lineChart(pts,unit,label){\n  if(pts.length<2)return `<p class=\"sub\" style=\"margin-top:8px\">Registra al menos dos pesajes para ver la gr\u00e1fica.</p>`;\n  const W=320,H=140,Pd=26,vals=pts.map(p=>p.v),mn=Math.floor(Math.min(...vals)-1),mx=Math.ceil(Math.max(...vals)+1);\n  const x=i=>Pd+(W-2*Pd)*i/(pts.length-1),y=v=>H-Pd-(H-2*Pd)*(v-mn)/(mx-mn||1);\n  const path=pts.map((p,i)=>`${i?\"L\":\"M\"}${x(i).toFixed(1)} ${y(p.v).toFixed(1)}`).join(\" \");\n  const dots=pts.map((p,i)=>`<circle cx=\"${x(i).toFixed(1)}\" cy=\"${y(p.v).toFixed(1)}\" r=\"4\" fill=\"#e9559b\"/>`).join(\"\");\n  const last=pts[pts.length-1];\n  return `<svg class=\"chart\" viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"${esc(label)}\">\n    <text x=\"4\" y=\"${y(mx)+4}\" font-size=\"10\" fill=\"#8d5a74\">${mx}</text><text x=\"4\" y=\"${y(mn)+4}\" font-size=\"10\" fill=\"#8d5a74\">${mn}</text>\n    <line x1=\"${Pd}\" x2=\"${W-Pd}\" y1=\"${y(mn)}\" y2=\"${y(mn)}\" stroke=\"#f5c3dc\"/><line x1=\"${Pd}\" x2=\"${W-Pd}\" y1=\"${y(mx)}\" y2=\"${y(mx)}\" stroke=\"#f5c3dc\"/>\n    <path d=\"${path}\" fill=\"none\" stroke=\"#e9559b\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/>${dots}\n    <text x=\"${x(pts.length-1)}\" y=\"${y(last.v)-10}\" font-size=\"11\" font-weight=\"800\" fill=\"#c42b78\" text-anchor=\"end\">${last.v} ${unit}</text></svg>`;\n}\nfunction spark(vals){\n  if(vals.length<2)return \"\";\n  const W=70,H=26,mn=Math.min(...vals),mx=Math.max(...vals);\n  const pts=vals.map((v,i)=>`${(i/(vals.length-1)*(W-4)+2).toFixed(1)},${(H-3-(H-6)*(v-mn)/((mx-mn)||1)).toFixed(1)}`).join(\" \");\n  return `<svg width=\"${W}\" height=\"${H}\" viewBox=\"0 0 ${W} ${H}\" aria-hidden=\"true\"><polyline points=\"${pts}\" fill=\"none\" stroke=\"#e9559b\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>`;\n}\nfunction muscleSVG(group){\n  const r=REG[group]||[],h=k=>r.includes(k)?\"#e9559b\":\"#f0c6d9\",b=\"#f8e1ec\";\n  const front=`<g><circle cx=\"50\" cy=\"14\" r=\"10\" fill=\"${b}\"/><rect x=\"34\" y=\"32\" width=\"32\" height=\"70\" rx=\"12\" fill=\"${b}\"/>\n   <ellipse cx=\"30\" cy=\"40\" rx=\"9\" ry=\"8\" fill=\"${h(\"shoulder\")}\"/><ellipse cx=\"70\" cy=\"40\" rx=\"9\" ry=\"8\" fill=\"${h(\"shoulder\")}\"/>\n   <rect x=\"19\" y=\"48\" width=\"9\" height=\"28\" rx=\"4\" fill=\"${h(\"biceps\")}\"/><rect x=\"72\" y=\"48\" width=\"9\" height=\"28\" rx=\"4\" fill=\"${h(\"biceps\")}\"/>\n   <rect x=\"17\" y=\"78\" width=\"9\" height=\"30\" rx=\"4\" fill=\"${b}\"/><rect x=\"74\" y=\"78\" width=\"9\" height=\"30\" rx=\"4\" fill=\"${b}\"/>\n   <rect x=\"42\" y=\"60\" width=\"16\" height=\"36\" rx=\"6\" fill=\"${h(\"abs\")}\"/>\n   <rect x=\"34\" y=\"104\" width=\"14\" height=\"46\" rx=\"6\" fill=\"${h(\"quads\")}\"/><rect x=\"52\" y=\"104\" width=\"14\" height=\"46\" rx=\"6\" fill=\"${h(\"quads\")}\"/>\n   <rect x=\"35\" y=\"152\" width=\"12\" height=\"38\" rx=\"5\" fill=\"${b}\"/><rect x=\"53\" y=\"152\" width=\"12\" height=\"38\" rx=\"5\" fill=\"${b}\"/></g>`;\n  const back=`<g transform=\"translate(120 0)\"><circle cx=\"50\" cy=\"14\" r=\"10\" fill=\"${b}\"/><rect x=\"34\" y=\"32\" width=\"32\" height=\"70\" rx=\"12\" fill=\"${b}\"/>\n   <ellipse cx=\"30\" cy=\"40\" rx=\"9\" ry=\"8\" fill=\"${h(\"shoulder\")}\"/><ellipse cx=\"70\" cy=\"40\" rx=\"9\" ry=\"8\" fill=\"${h(\"shoulder\")}\"/>\n   <path d=\"M38 36 L62 36 L66 74 L34 74Z\" fill=\"${h(\"back\")}\"/>\n   <rect x=\"19\" y=\"48\" width=\"9\" height=\"28\" rx=\"4\" fill=\"${h(\"triceps\")}\"/><rect x=\"72\" y=\"48\" width=\"9\" height=\"28\" rx=\"4\" fill=\"${h(\"triceps\")}\"/>\n   <rect x=\"17\" y=\"78\" width=\"9\" height=\"30\" rx=\"4\" fill=\"${b}\"/><rect x=\"74\" y=\"78\" width=\"9\" height=\"30\" rx=\"4\" fill=\"${b}\"/>\n   <ellipse cx=\"41\" cy=\"97\" rx=\"10\" ry=\"9\" fill=\"${h(\"glutes\")}\"/><ellipse cx=\"59\" cy=\"97\" rx=\"10\" ry=\"9\" fill=\"${h(\"glutes\")}\"/>\n   <rect x=\"34\" y=\"110\" width=\"14\" height=\"40\" rx=\"6\" fill=\"${h(\"hams\")}\"/><rect x=\"52\" y=\"110\" width=\"14\" height=\"40\" rx=\"6\" fill=\"${h(\"hams\")}\"/>\n   <rect x=\"35\" y=\"152\" width=\"12\" height=\"38\" rx=\"5\" fill=\"${b}\"/><rect x=\"53\" y=\"152\" width=\"12\" height=\"38\" rx=\"5\" fill=\"${b}\"/></g>`;\n  return `<svg viewBox=\"0 0 220 200\" style=\"width:100%;max-width:240px;height:auto;display:block;margin:8px auto 0\" role=\"img\" aria-label=\"M\u00fasculos que trabaja: ${esc(group)}\">${front}${back}\n   <text x=\"50\" y=\"199\" font-size=\"9\" fill=\"#8d5a74\" text-anchor=\"middle\" font-weight=\"700\">Frente</text><text x=\"170\" y=\"199\" font-size=\"9\" fill=\"#8d5a74\" text-anchor=\"middle\" font-weight=\"700\">Espalda</text></svg>`;\n}\nfunction avatarSVG(a,size){\n  const skin=SKIN[a.skin]||SKIN[1],hair=HAIR[a.hair]||HAIR[0],band=BAND[a.band]||BAND[0],s=a.style;\n  let back=\"\",front=\"\";\n  const fringe=`<path d=\"M29 48 Q33 27 50 29 Q67 27 71 48 Q60 36 50 38 Q40 36 29 48Z\" fill=\"${hair}\"/>`;\n  if(s===0){\n    back=[[28,40],[24,52],[26,64],[72,40],[76,52],[74,64],[34,28],[46,24],[58,24],[68,28],[50,22]].map(p=>`<circle cx=\"${p[0]}\" cy=\"${p[1]}\" r=\"12\" fill=\"${hair}\"/>`).join(\"\");\n    front=fringe;\n  }else if(s===1){\n    back=`<ellipse cx=\"50\" cy=\"44\" rx=\"24\" ry=\"22\" fill=\"${hair}\"/><path d=\"M70 36 Q95 42 86 76 Q84 58 72 52Z\" fill=\"${hair}\"/>`;\n    front=fringe+`<circle cx=\"72\" cy=\"40\" r=\"5\" fill=\"${band}\"/>`;\n  }else if(s===2){\n    back=`<circle cx=\"50\" cy=\"20\" r=\"11\" fill=\"${hair}\"/><ellipse cx=\"50\" cy=\"42\" rx=\"24\" ry=\"20\" fill=\"${hair}\"/>`;\n    front=fringe+`<ellipse cx=\"50\" cy=\"30\" rx=\"9\" ry=\"3.2\" fill=\"${band}\"/>`;\n  }else{\n    back=`<path d=\"M26 46 Q26 24 50 24 Q74 24 74 46 L79 88 L21 88Z\" fill=\"${hair}\"/>`;\n    front=fringe;\n  }\n  return `<svg width=\"${size}\" height=\"${size}\" viewBox=\"0 0 100 100\" class=\"av\" style=\"width:${size}px;height:${size}px\" role=\"img\" aria-label=\"Avatar\">\n   <defs><clipPath id=\"c${size}\"><circle cx=\"50\" cy=\"50\" r=\"50\"/></clipPath></defs>\n   <g clip-path=\"url(#c${size})\"><rect width=\"100\" height=\"100\" fill=\"#ffd9ea\"/>${back}\n   <path d=\"M16 104 Q20 82 50 82 Q80 82 84 104Z\" fill=\"#e9559b\"/><rect x=\"43\" y=\"72\" width=\"14\" height=\"14\" rx=\"5\" fill=\"${skin}\"/>\n   <ellipse cx=\"50\" cy=\"54\" rx=\"22\" ry=\"25\" fill=\"${skin}\"/>${front}\n   <circle cx=\"42\" cy=\"55\" r=\"2.6\" fill=\"#3b2216\"/><circle cx=\"58\" cy=\"55\" r=\"2.6\" fill=\"#3b2216\"/>\n   <path d=\"M43 64 Q50 71 57 64\" fill=\"none\" stroke=\"#9a3a5c\" stroke-width=\"2.2\" stroke-linecap=\"round\"/>\n   <circle cx=\"36\" cy=\"62\" r=\"4\" fill=\"#ff8fb8\" opacity=\".35\"/><circle cx=\"64\" cy=\"62\" r=\"4\" fill=\"#ff8fb8\" opacity=\".35\"/></g></svg>`;\n}\nfunction avatarHTML(size){\n  const a=state.avatar;\n  if(a.mode===\"photo\"&&a.photo)return `<img class=\"av\" src=\"${a.photo}\" width=\"${size}\" height=\"${size}\" style=\"width:${size}px;height:${size}px\" alt=\"Foto de perfil\">`;\n  return avatarSVG(a,size);\n}\n\n/* ============ MODAL ============ */\nfunction openModal(html){\n  const m=$(\"modal\");m.innerHTML=`<div class=\"sheet\" role=\"dialog\" aria-modal=\"true\">${html}</div>`;m.hidden=false;document.body.style.overflow=\"hidden\";\n  m.querySelectorAll(\"[data-close]\").forEach(b=>b.onclick=closeModal);\n}\nfunction closeModal(){const m=$(\"modal\");m.hidden=true;m.innerHTML=\"\";document.body.style.overflow=\"\"}\n$(\"modal\").onclick=e=>{if(e.target===$(\"modal\"))closeModal()};\ndocument.addEventListener(\"keydown\",e=>{if(e.key===\"Escape\")closeModal()});\n\nfunction fichaModal(info){\n  const hist=state.hist[info.name]||[];\n  const how=info.how?info.how[0].split(\"|\").map(s=>`<li>${esc(s)}</li>`).join(\"\"):`<li>${esc(info.tip)}</li>`;\n  const q=encodeURIComponent(info.name+\" t\u00e9cnica ejercicio gimnasio\");\n  const pc=pctChange(info.name);\n  openModal(`<button class=\"x\" data-close aria-label=\"Cerrar\">\u2715</button>\n   <h2 style=\"margin-right:44px\">${esc(info.name)}</h2>\n   <div style=\"margin-top:6px\"><span class=\"pill\">${esc(info.group)}</span> ${info.alt?`<span class=\"pill sw2\">Alternativa</span>`:\"\"} <span class=\"pill\">${info.sets} \u00d7 ${esc(info.reps)}${info.rest?` \u00b7 descanso ${info.rest} s`:\"\"}</span></div>\n   ${muscleSVG(info.group)}\n   <h3 style=\"font-size:16px;margin-top:10px\">C\u00f3mo hacerlo</h3><ol class=\"steps\">${how}</ol>\n   ${info.how?`<div class=\"note\"><b>Error com\u00fan:</b> ${esc(info.how[1])}</div>`:\"\"}\n   <div class=\"note\" style=\"background:var(--rose)\"><b>Consejo:</b> ${esc(info.tip)}</div>\n   <h3 style=\"font-size:16px;margin-top:14px\">Historial de pesos${pc!==null?` \u00b7 <span class=\"${cls(pc)}\">${fmtPct(pc)}</span>`:\"\"}</h3>\n   ${hist.length?`${lineChart(hist.map(e=>({v:e.kg})),\"kg\",\"Evoluci\u00f3n de peso en \"+info.name)}<div class=\"hist\">${[...hist].reverse().slice(0,8).map(e=>`<span>${shortDate(e.d)} \u00b7 ${e.kg} kg</span>`).join(\"\")}</div>`:`<p class=\"sub\" style=\"margin-top:6px\">A\u00fan no hay pesos registrados. An\u00f3talos en la tarjeta del ejercicio.</p>`}\n   <div class=\"row\" style=\"margin-top:14px\"><a class=\"btn sm grow\" target=\"_blank\" rel=\"noopener\" href=\"https://www.youtube.com/results?search_query=${q}\">\u25b6 Ver video</a><a class=\"btn sec sm grow\" target=\"_blank\" rel=\"noopener\" href=\"https://www.google.com/search?tbm=isch&q=${q}\">\ud83d\uddbc Ver im\u00e1genes</a></div>\n   <p class=\"sub\" style=\"margin-top:8px;font-size:12px\">Los videos e im\u00e1genes se abren en YouTube y Google. Compara la t\u00e9cnica con varias referencias.</p>\n   ${info.d!==undefined?`<button class=\"btn sec\" style=\"margin-top:10px\" data-swapfrom=\"${info.d}-${info.i}\">\u00bfMolestia? Cambiar ejercicio</button>`:\"\"}`);\n  document.querySelectorAll(\"[data-swapfrom]\").forEach(b=>b.onclick=()=>{const [d,i]=b.dataset.swapfrom.split(\"-\").map(Number);swapModal(d,i)});\n}\nlet zone=\"rodilla\";\nfunction swapModal(d,i){\n  const ex=DAYS[d].ex[i],alts=ALT[ex[0]]||[],sw=state.swap[`${d}-${i}`];\n  openModal(`<button class=\"x\" data-close aria-label=\"Cerrar\">\u2715</button>\n   <h2 style=\"margin-right:44px\">Cambiar ejercicio</h2>\n   <p class=\"sub\" style=\"margin-top:4px\">${esc(ex[0])}</p>\n   <div class=\"chips\" style=\"margin-top:10px\">${[[\"rodilla\",\"Rodilla\"],[\"cadera\",\"Cadera\"],[\"otra\",\"Otra molestia\"]].map(([k,l])=>`<button class=\"chip ${zone===k?\"on\":\"\"}\" data-zone=\"${k}\">${l}</button>`).join(\"\")}</div>\n   <div class=\"note\" style=\"margin-top:0\">${esc(ZONES[zone])}<br><br>Si el dolor es intenso o persiste, deja de entrenar esa zona y consulta con un profesional.</div>\n   <button class=\"opt ${sw===undefined?\"on\":\"\"}\" data-pick=\"-1\"><b>${esc(ex[0])}</b><span>Ejercicio original del plan</span></button>\n   ${alts.map((a,j)=>`<button class=\"opt ${sw===j?\"on\":\"\"}\" data-pick=\"${j}\"><b>${esc(a[0])}</b><span>${esc(a[1])}</span></button>`).join(\"\")}\n   <p class=\"sub\" style=\"margin-top:10px;font-size:12px\">El cambio se aplica a las 4 semanas. Mantiene las mismas series, repeticiones y descanso.</p>`);\n  document.querySelectorAll(\"[data-zone]\").forEach(b=>b.onclick=()=>{zone=b.dataset.zone;swapModal(d,i)});\n  document.querySelectorAll(\"[data-pick]\").forEach(b=>b.onclick=()=>{\n    const j=+b.dataset.pick,key=`${d}-${i}`;\n    if(j<0)delete state.swap[key];else state.swap[key]=j;\n    for(let w=state.week;w<=4;w++)delete state.kg[kx(w,d,i)];\n    save();closeModal();render();toast(j<0?\"Ejercicio original restaurado\":\"Ejercicio cambiado\");\n  });\n}\n\n/* ============ VISTAS ============ */\nconst ICONS={\n home:'<svg viewBox=\"0 0 24 24\"><path d=\"M3 11l9-8 9 8\"/><path d=\"M5 10v10h14V10\"/></svg>',\n plan:'<svg viewBox=\"0 0 24 24\"><path d=\"M6.5 6.5v11M17.5 6.5v11M3.5 9v6M20.5 9v6M6.5 12h11\"/></svg>',\n cal:'<svg viewBox=\"0 0 24 24\"><rect x=\"3.5\" y=\"5\" width=\"17\" height=\"15.5\" rx=\"3\"/><path d=\"M3.5 10h17M8 3v4M16 3v4\"/></svg>',\n prog:'<svg viewBox=\"0 0 24 24\"><path d=\"M3 17l6-6 4 4 8-9\"/><path d=\"M15 6h6v6\"/></svg>',\n me:'<svg viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"8\" r=\"4\"/><path d=\"M4 21c1-4 4-6 8-6s7 2 8 6\"/></svg>'\n};\nconst NAV=[[\"home\",\"Inicio\"],[\"plan\",\"Rutina\"],[\"cal\",\"Calendario\"],[\"prog\",\"Progreso\"],[\"me\",\"Perfil\"]];\nfunction drawNav(){\n  $(\"nav\").innerHTML=NAV.map(([v,l])=>`<button class=\"${state.view===v?\"on\":\"\"}\" data-v=\"${v}\" aria-label=\"${l}\">${ICONS[v]}${l}</button>`).join(\"\");\n  $(\"nav\").querySelectorAll(\"button\").forEach(b=>b.onclick=()=>{state.view=b.dataset.v;save();render();window.scrollTo(0,0)});\n}\n\nfunction viewHome(){\n  const now=bogota(),cw=currentWeek(),wp=weekProgress(cw),pp=planProgress(),nx=nextWorkout();\n  const mon=mondayOf(now.iso);\n  const strip=[0,1,2,3,4,5,6].map(i=>{\n    const d=PLAN_WD[i],iso=addDays(mon,i),w=weekOf(iso);\n    let mark=\"\u00b7\";\n    if(d!==undefined){mark=(w>=1&&w<=4&&state.log[`${w}-${d}`])?\"\u2713\":\"\u25cf\"}\n    return `<div class=\"${i===now.wd?\"today\":\"\"} ${mark===\"\u2713\"?\"done\":\"\"}\">${WD_LAB[i]}<i>${mark===\"\u25cf\"?`<span style=\"color:var(--pink)\">\u25cf</span>`:mark}</i></div>`;\n  }).join(\"\");\n  let next=\"\";\n  if(nx){\n    const D=DAYS[nx.d];\n    next=`<span class=\"pill\">${relDay(nx.o,nx.iso)} \u00b7 Semana ${nx.w}</span>\n      <h3 style=\"font-size:19px;font-weight:800;margin-top:7px\">D\u00eda ${nx.d+1} \u00b7 ${esc(D.n)}</h3>\n      <p class=\"sub\">${D.ex.length} ejercicios \u00b7 aprox. 60 min</p>\n      <button class=\"btn\" style=\"margin-top:12px\" data-go=\"${nx.d}\" data-gw=\"${nx.w}\">Ir a la rutina</button>`;\n  }else next=`<h3 style=\"font-size:19px;font-weight:800\">\ud83c\udf89 \u00a1Completaste las 4 semanas!</h3><p class=\"sub\" style=\"margin-top:6px\">Mira tu evoluci\u00f3n o empieza un nuevo ciclo desde Perfil.</p>`;\n  const st=strengthTotal();\n  return `\n  <div class=\"top\"><div><div class=\"brand\">Chiky Gym</div><div class=\"sub\">Hola, ${esc(P().name||\"Chiky\")} \ud83d\udc97</div></div>\n   <button class=\"avbtn\" data-v2=\"me\" aria-label=\"Ir a mi perfil\">${avatarHTML(58)}</button></div>\n  <div class=\"card clock\">\n    <div class=\"t\" id=\"hm\">${now.time}</div>\n    <div class=\"grow\"><div class=\"d\" id=\"dt\">${now.date}</div><div class=\"z\">Bogot\u00e1, Colombia (UTC\u22125)</div></div>\n  </div>\n  <h2>Tu pr\u00f3ximo entrenamiento</h2>\n  <div class=\"card\">${next}</div>\n  <h2>Resumen semanal \u00b7 Semana ${cw}</h2>\n  <div class=\"card\">\n    <div class=\"row\">\n      <div class=\"ring\" style=\"--p:${wp.p}\"><b>${wp.p}%</b></div>\n      <div class=\"stats grow\">\n        <div>${sessionsDone(cw)} de 4 <span>entrenamientos</span></div>\n        <div>${wp.c} de ${wp.t} <span>series completadas</span></div>\n        <div>${WEEKS[cw][0]} <span>\u00b7 fase de la semana</span></div>\n      </div>\n    </div>\n    <div class=\"strip\">${strip}</div>\n  </div>\n  <h2>Plan de 4 semanas</h2>\n  <div class=\"card\">\n    <div class=\"row\" style=\"justify-content:space-between\"><b>${pp.p}% del plan</b><span class=\"sub\">${[1,2,3,4].reduce((a,w)=>a+sessionsDone(w),0)} de 16 sesiones</span></div>\n    <div class=\"bar\" style=\"margin:8px 0 12px\"><i style=\"width:${pp.p}%\"></i></div>\n    <div class=\"kv\" style=\"grid-template-columns:repeat(3,1fr)\"><div><b>${lastBody()}</b><span>kg actual</span></div><div><b class=\"${cls(st)}\">${fmtPct(st)}</b><span>fuerza total</span></div><div><b>${imc()}</b><span>IMC</span></div></div>\n  </div>`;\n}\n\nfunction viewPlan(){\n  const w=state.week,d=state.day,D=DAYS[d],dp=dayProgress(w,d);\n  const wkTabs=[1,2,3,4].map(x=>`<button class=\"chip ${x===w?\"on\":\"\"}\" data-week=\"${x}\">Semana ${x}</button>`).join(\"\");\n  const dTabs=DAYS.map((_,i)=>`<button class=\"chip ${i===d?\"on\":\"\"}\" data-day=\"${i}\">D\u00eda ${i+1}</button>`).join(\"\");\n  const exs=D.ex.map((ex,i)=>{\n    const info=exInfo(d,i),k=kx(w,d,i),s=setsFor(ex,w),n=Math.min(s,+state.done[k]||0),rest=state.rest[k]??ex[4];\n    const pv=prevHist(info.name,w);\n    const btns=Array.from({length:s},(_,j)=>`<button class=\"set ${j<n?\"on\":\"\"}\" data-set=\"${i}\" data-n=\"${j+1}\" aria-label=\"Serie ${j+1}\" aria-pressed=\"${j<n}\">${j<n?\"\u2713\":j+1}</button>`).join(\"\");\n    const restUi=ex[4]?`<div class=\"rests\">Descanso ${[30,45,60,75,90].map(x=>`<button class=\"${rest===x?\"on\":\"\"}\" data-rest=\"${i}\" data-s=\"${x}\">${x}s</button>`).join(\"\")}</div>`:\"\";\n    const kgUi=ex[3].includes(\"min\")?\"\":`<label class=\"kg\">Peso <input type=\"text\" inputmode=\"decimal\" placeholder=\"kg\" value=\"${esc(state.kg[k]||\"\")}\" data-kg=\"${i}\" aria-label=\"Peso en kg\"> kg</label>${pv?`<span class=\"prev\">Antes: ${pv.kg} kg (sem. ${pv.w})</span>`:\"\"}`;\n    return `<article class=\"ex ${n>=s?\"ok\":\"\"}\">\n      <div class=\"ex-h\"><div><span class=\"pill\">${esc(ex[1])}${ex[5]&&w===3?\" \u2605\":\"\"}</span>${info.alt?` <span class=\"pill sw2\">Alternativa</span>`:\"\"}<h3 style=\"margin-top:6px\">${esc(info.name)}</h3></div><div class=\"target\">${s} \u00d7 ${esc(ex[3])}</div></div>\n      <p>${esc(info.tip)}</p>\n      <div class=\"sets\">${btns}</div>\n      <div class=\"meta\">${kgUi}${restUi}</div>\n      <div class=\"acts\"><button class=\"link\" data-info=\"${i}\">\u2139 Ficha del ejercicio</button><button class=\"link\" data-swap=\"${i}\">\u00bfMolestia? Cambiar</button></div>\n    </article>`;\n  }).join(\"\");\n  return `\n  <div class=\"top\"><div><h1 style=\"font-size:24px;font-weight:800\">Rutinas</h1><div class=\"sub\">4 d\u00edas \u00b7 60 min por sesi\u00f3n</div></div><span class=\"pill\">${dp.p}%</span></div>\n  <div class=\"chips\">${wkTabs}</div>\n  <div class=\"chips\">${dTabs}</div>\n  <div class=\"card\">\n    <h3 style=\"font-size:19px;font-weight:800\">D\u00eda ${d+1} \u00b7 ${esc(D.n)}</h3>\n    <p class=\"sub\">${esc(D.tag)} \u00b7 Semana ${w}: ${WEEKS[w][0]}</p>\n    <div class=\"bar\" style=\"margin:10px 0 4px\"><i style=\"width:${dp.p}%\"></i></div>\n    <div class=\"sub\">${dp.c} de ${dp.t} series completadas</div>\n    <div class=\"note\"><b>Antes de empezar:</b> ${esc(D.intro)}<br><br><b>${WEEKS[w][0]}:</b> ${esc(WEEKS[w][1])}</div>\n    <div class=\"note\" style=\"background:var(--rose)\"><b>Molestias:</b> si aparece dolor en rodilla o cadera, toca \u00ab\u00bfMolestia? Cambiar\u00bb en el ejercicio y elige una alternativa.</div>\n    <div class=\"chips\" style=\"margin-top:10px;padding-bottom:0\"><button class=\"chip ${state.auto?\"on\":\"\"}\" id=\"autoT\">\u23f1 Descanso autom\u00e1tico: ${state.auto?\"S\u00ed\":\"No\"}</button></div>\n  </div>\n  ${exs}\n  ${dp.t&&dp.c>=dp.t?`<div class=\"win\">\ud83c\udf89 \u00a1Sesi\u00f3n completa!<div class=\"sub\" style=\"margin-top:4px\">Estira 5 min: espalda, cadera y pecho.</div></div>`:\"\"}\n  <div style=\"margin-top:14px\"><button class=\"btn sec\" id=\"resetDay\">Reiniciar este d\u00eda y semana</button></div>`;\n}\n\nfunction viewCal(){\n  const now=bogota();if(!state.calMonth)state.calMonth=now.iso.slice(0,7);\n  const ym=state.calMonth,[Y,M]=ym.split(\"-\").map(Number);\n  const dow=wdOf(`${ym}-01`),dim=new Date(Date.UTC(Y,M,0)).getUTCDate();\n  const ss=sessionsList(),by={};ss.forEach(s=>(by[s.date]=by[s.date]||[]).push(s));\n  let cells=WD_LAB.map(l=>`<div class=\"dw\">${l}</div>`).join(\"\");\n  for(let i=0;i<dow;i++)cells+=`<div class=\"cell e\"></div>`;\n  for(let n=1;n<=dim;n++){\n    const iso=`${ym}-${pad(n)}`,wdi=(dow+n-1)%7,w=weekOf(iso),planned=(wdi in PLAN_WD)&&w>=1&&w<=4,d=PLAN_WD[wdi];\n    const dn=by[iso],t=iso===now.iso?\" today\":\"\";\n    if(dn)cells+=`<div class=\"cell done${t}\" title=\"Entrenado\">${n}<i>\u2713 ${dn.map(s=>\"D\"+(s.day+1)).join(\",\")}</i></div>`;\n    else if(planned&&iso>=now.iso)cells+=`<button class=\"cell plan${t}\" data-cgo=\"${d}-${w}\" aria-label=\"D\u00eda ${d+1} programado el ${n}\">${n}<i>D${d+1}</i></button>`;\n    else if(planned&&!state.log[`${w}-${d}`])cells+=`<div class=\"cell miss${t}\" title=\"Sin completar\">${n}<i>\u2013</i></div>`;\n    else cells+=`<div class=\"cell${t}\">${n}<i></i></div>`;\n  }\n  const inMonth=ss.filter(s=>s.date.startsWith(ym)).length;\n  const weeks=[1,2,3,4].map(w=>{\n    const x=weekProgress(w),a=addDays(state.start,(w-1)*7);\n    return `<div style=\"margin-top:10px\"><div class=\"row\" style=\"justify-content:space-between\"><b>Semana ${w}</b><span class=\"sub\">${shortDate(a)} \u2013 ${shortDate(addDays(a,6))} \u00b7 ${sessionsDone(w)}/4 sesiones</span></div><div class=\"bar\" style=\"margin-top:5px\"><i style=\"width:${Math.round(sessionsDone(w)/4*100)}%\"></i></div><div class=\"sub\" style=\"font-size:12px;margin-top:3px\">Cumplimiento ${Math.round(sessionsDone(w)/4*100)}% \u00b7 series ${x.p}%</div></div>`;\n  }).join(\"\");\n  return `\n  <div class=\"top\"><div><h1 style=\"font-size:24px;font-weight:800\">Calendario</h1><div class=\"sub\">Tus entrenamientos y cumplimiento</div></div></div>\n  <div class=\"card\">\n    <div class=\"calh\"><button class=\"chip\" data-cm=\"-1\" aria-label=\"Mes anterior\">\u2039</button><b>${monthLabel(ym)}</b><button class=\"chip\" data-cm=\"1\" aria-label=\"Mes siguiente\">\u203a</button></div>\n    <div class=\"cal\">${cells}</div>\n    <div class=\"legend\"><span>\u2713 Entrenado</span><span style=\"color:var(--pink)\">\u25cf Programado (toca para ir)</span><span>\u2013 Sin completar</span></div>\n    <p class=\"sub\" style=\"margin-top:8px\"><b>${inMonth}</b> ${inMonth===1?\"sesi\u00f3n\":\"sesiones\"} en este mes.</p>\n  </div>\n  <h2>Cumplimiento semanal</h2>\n  <div class=\"card\">${weeks.replace(/^<div style=\"margin-top:10px\">/,\"<div>\")}</div>`;\n}\n\nfunction viewProg(){\n  const tabs=[[\"gen\",\"General\"],[\"str\",\"Fuerza\"],[\"mon\",\"Mensual\"]].map(([k,l])=>`<button class=\"chip ${state.progTab===k?\"on\":\"\"}\" data-pt=\"${k}\">${l}</button>`).join(\"\");\n  let body=\"\";\n  if(state.progTab===\"str\")body=progStr();else if(state.progTab===\"mon\")body=progMon();else body=progGen();\n  return `<div class=\"top\"><div><h1 style=\"font-size:24px;font-weight:800\">Progreso</h1><div class=\"sub\">Tu avance paso a paso</div></div></div><div class=\"chips\">${tabs}</div>${body}`;\n}\nfunction progGen(){\n  const pp=planProgress();\n  const weeks=[1,2,3,4].map(w=>{const x=weekProgress(w);return `<div style=\"margin-top:10px\"><div class=\"row\" style=\"justify-content:space-between\"><b>Semana ${w} \u00b7 ${WEEKS[w][0]}</b><span class=\"sub\">${sessionsDone(w)}/4 sesiones \u00b7 ${x.p}%</span></div><div class=\"bar\" style=\"margin-top:5px\"><i style=\"width:${x.p}%\"></i></div></div>`}).join(\"\");\n  const hist=[...bodySorted()].reverse().slice(0,5).map(b=>`<tr><td>${shortDate(b.date)}</td><td>${b.kg} kg</td></tr>`).join(\"\");\n  const st=strengthTotal(),kg=lastBody();\n  return `\n  <div class=\"card\"><div class=\"row\"><div class=\"ring\" style=\"--p:${pp.p}\"><b>${pp.p}%</b></div>\n    <div class=\"grow stats\"><div>${pp.c} de ${pp.t} <span>series totales</span></div><div>${[1,2,3,4].reduce((a,w)=>a+sessionsDone(w),0)} de 16 <span>sesiones</span></div><div class=\"${cls(st)}\">${fmtPct(st)} <span>fuerza total</span></div></div></div>\n    ${weeks}</div>\n  <h2>Peso corporal</h2>\n  <div class=\"card\">\n    ${lineChart(bodySorted().slice(-12).map(b=>({v:b.kg})),\"kg\",\"Evoluci\u00f3n del peso corporal\")}\n    <div class=\"inl\"><input id=\"bkg\" type=\"text\" inputmode=\"decimal\" placeholder=\"Hoy: ${kg} kg\" aria-label=\"Peso corporal de hoy\"><button class=\"btn sm\" id=\"addBody\">Guardar</button></div>\n    ${hist?`<div class=\"tbl\"><table><tbody>${hist}</tbody></table></div>`:\"\"}\n    <div class=\"kv\" style=\"margin-top:12px\"><div><b>${kg}</b><span>kg</span></div><div><b>${P().cm}</b><span>cm</span></div><div><b>${imc()}</b><span>IMC</span></div><div><b>${P().age}</b><span>a\u00f1os</span></div></div>\n  </div>`;\n}\nfunction progStr(){\n  const names=[];\n  DAYS.forEach(D=>D.ex.forEach(ex=>{[ex[0],...(ALT[ex[0]]||[]).map(a=>a[0])].forEach(n=>{if(state.hist[n]&&!names.includes(n))names.push(n)})}));\n  Object.keys(state.hist).forEach(n=>{if(!names.includes(n))names.push(n)});\n  const st=strengthTotal();\n  const list=names.map(n=>{\n    const a=state.hist[n],pc=pctChange(n);\n    return `<button class=\"opt\" data-ficha=\"${esc(n)}\" style=\"display:flex;align-items:center;gap:10px\"><span class=\"grow\" style=\"display:block\"><b>${esc(n)}</b><span>${a[0].kg} \u2192 ${a[a.length-1].kg} kg \u00b7 ${a.length} ${a.length===1?\"registro\":\"registros\"}</span></span>${spark(a.map(e=>e.kg))}<b class=\"${cls(pc)}\" style=\"min-width:52px;text-align:right\">${fmtPct(pc)}</b></button>`;\n  }).join(\"\");\n  return `<div class=\"card\"><div class=\"row\"><div class=\"ring\" style=\"--p:${st===null?0:Math.min(100,Math.max(0,st*4))}\"><b class=\"${cls(st)}\" style=\"font-size:17px\">${fmtPct(st)}</b></div>\n   <div class=\"grow\"><b>Fuerza total</b><p class=\"sub\">Promedio del cambio de peso en tus ejercicios frente al primer registro. Necesitas al menos dos registros por ejercicio.</p></div></div></div>\n   <h2>Historial por ejercicio</h2>\n   ${list||`<div class=\"card\"><p class=\"sub\">A\u00fan no hay pesos registrados. Escribe el peso en cada ejercicio de tu rutina y aqu\u00ed ver\u00e1s si est\u00e1s ganando fuerza.</p></div>`}`;\n}\nfunction progMon(){\n  const set=new Set([bogota().iso.slice(0,7)]);\n  sessionsList().forEach(s=>set.add(s.date.slice(0,7)));\n  state.body.forEach(b=>set.add(b.date.slice(0,7)));\n  Object.keys(state.cnt).forEach(d=>set.add(d.slice(0,7)));\n  Object.values(state.hist).forEach(a=>a.forEach(e=>set.add(e.d.slice(0,7))));\n  const months=[...set].sort().reverse(),bs=bodySorted();\n  const cards=months.map(ym=>{\n    const ses=sessionsList().filter(s=>s.date.startsWith(ym)).length;\n    const sets=Object.entries(state.cnt).filter(([d])=>d.startsWith(ym)).reduce((a,[,v])=>a+v,0);\n    const inM=bs.filter(b=>b.date.startsWith(ym)),before=bs.filter(b=>b.date<ym+\"-01\");\n    const kg=inM.length?inM[inM.length-1].kg:null,base=before.length?before[before.length-1].kg:P().kg0;\n    const dk=kg!==null?+(kg-base).toFixed(1):null,sm=strengthMonth(ym);\n    return `<div class=\"card\"><b style=\"text-transform:capitalize;font-size:17px\">${monthLabel(ym)}</b>\n      <div class=\"kv\" style=\"margin-top:8px\"><div><b>${ses}</b><span>sesiones</span></div><div><b>${sets}</b><span>series</span></div><div><b>${kg!==null?kg:\"\u2013\"}</b><span>kg${dk!==null&&dk!==0?` (${dk>0?\"+\":\"\"}${dk})`:\"\"}</span></div><div><b class=\"${cls(sm)}\">${fmtPct(sm)}</b><span>fuerza</span></div></div></div>`;\n  }).join(\"\");\n  return `<p class=\"sub\" style=\"margin:0 4px 8px\">Resumen por mes: sesiones completadas, series, peso corporal al cierre y cambio de fuerza frente a tu primer registro.</p>${cards}`;\n}\n\nfunction swatches(list,key,cur,labels){\n  return list.map((c,i)=>`<button class=\"sw ${cur===i?\"on\":\"\"}\" style=\"background:${c}\" data-av=\"${key}\" data-i=\"${i}\" aria-label=\"${labels} ${i+1}\"></button>`).join(\"\");\n}\nfunction viewMe(){\n  const p=P(),a=state.avatar,cw=currentWeek();\n  return `\n  <div class=\"top\"><div><h1 style=\"font-size:24px;font-weight:800\">Tu perfil</h1><div class=\"sub\">Miembro Chiky \ud83d\udc97</div></div></div>\n  <div class=\"card\" style=\"text-align:center\">\n    <div style=\"display:grid;place-items:center\">${avatarHTML(110)}</div>\n    <h3 style=\"font-size:20px;font-weight:800;margin-top:8px\">${esc(p.name||\"Chiky\")}</h3>\n    <div class=\"kv\" style=\"margin-top:10px\"><div><b>${p.age}</b><span>a\u00f1os</span></div><div><b>${lastBody()}</b><span>kg</span></div><div><b>${p.cm}</b><span>cm</span></div><div><b>${imc()}</b><span>IMC</span></div></div>\n  </div>\n  <h2>Avatar</h2>\n  <div class=\"card\">\n    <div class=\"chips\" style=\"padding-bottom:4px\"><button class=\"chip ${a.mode===\"svg\"?\"on\":\"\"}\" data-mode=\"svg\">Avatar</button><button class=\"chip ${a.mode===\"photo\"?\"on\":\"\"}\" data-mode=\"photo\">Foto</button></div>\n    ${a.mode===\"svg\"?`\n      <div class=\"fld\">Piel</div><div class=\"row\" style=\"margin-top:6px;flex-wrap:wrap\">${swatches(SKIN,\"skin\",a.skin,\"Piel\")}</div>\n      <div class=\"fld\">Cabello</div><div class=\"row\" style=\"margin-top:6px;flex-wrap:wrap\">${swatches(HAIR,\"hair\",a.hair,\"Cabello\")}</div>\n      <div class=\"fld\">Peinado</div><div class=\"chips\" style=\"margin-top:6px\">${STYLES.map((s,i)=>`<button class=\"chip ${a.style===i?\"on\":\"\"}\" data-av=\"style\" data-i=\"${i}\">${s}</button>`).join(\"\")}</div>\n      <div class=\"fld\">Accesorio</div><div class=\"row\" style=\"margin-top:6px;flex-wrap:wrap\">${swatches(BAND,\"band\",a.band,\"Accesorio\")}</div>`:\n      `<p class=\"sub\" style=\"margin-top:6px\">La foto se guarda solo en este dispositivo y se recorta en cuadrado.</p>\n       <input type=\"file\" id=\"photo\" accept=\"image/*\" hidden>\n       <button class=\"btn sec\" style=\"margin-top:10px\" id=\"pickPhoto\">${a.photo?\"Cambiar foto\":\"Subir foto\"}</button>`}\n  </div>\n  <h2>Datos personales y objetivos</h2>\n  <div class=\"card\">\n    <label class=\"fld\">Nombre<input id=\"f_name\" value=\"${esc(p.name||\"\")}\" maxlength=\"30\"></label>\n    <div class=\"two\"><label class=\"fld\">Edad<input id=\"f_age\" type=\"text\" inputmode=\"numeric\" value=\"${p.age}\"></label><label class=\"fld\">Estatura (cm)<input id=\"f_cm\" type=\"text\" inputmode=\"numeric\" value=\"${p.cm}\"></label></div>\n    <label class=\"fld\">Peso actual (kg)<input id=\"f_kg\" type=\"text\" inputmode=\"decimal\" value=\"${lastBody()}\"></label>\n    <label class=\"fld\">Objetivo<textarea id=\"f_goal\" rows=\"2\" maxlength=\"140\">${esc(p.goal||\"\")}</textarea></label>\n    <label class=\"fld\">Nivel<select id=\"f_level\">${[\"Principiante\",\"Intermedia\",\"Avanzada\"].map(l=>`<option ${p.level===l?\"selected\":\"\"}>${l}</option>`).join(\"\")}</select></label>\n    <label class=\"fld\">Limitaciones o molestias<input id=\"f_limits\" value=\"${esc(p.limits||\"\")}\" maxlength=\"100\"></label>\n    <label class=\"fld\">Material disponible<input id=\"f_mat\" value=\"${esc(p.material||\"\")}\" maxlength=\"100\"></label>\n    <button class=\"btn\" style=\"margin-top:14px\" id=\"saveProfile\">Guardar datos</button>\n  </div>\n  <h2>Entrenamiento</h2>\n  <div class=\"card\">\n    <button class=\"chip ${state.auto?\"on\":\"\"}\" id=\"autoT2\">\u23f1 Descanso autom\u00e1tico entre series: ${state.auto?\"S\u00ed\":\"No\"}</button>\n    <p class=\"sub\" style=\"margin-top:10px\">Tu plan empez\u00f3 el lunes ${shortDate(state.start)} y hoy est\u00e1s en la semana ${cw}. D\u00edas sugeridos: lunes, martes, jueves y viernes.</p>\n    <div style=\"margin-top:10px\"><button class=\"btn sec\" id=\"restart\">Empezar un nuevo ciclo de 4 semanas</button></div>\n    ${Object.keys(state.swap).length?`<div style=\"margin-top:8px\"><button class=\"btn sec\" id=\"clearSwap\">Restaurar ejercicios originales</button></div>`:\"\"}\n  </div>\n  <h2>Sincronizaci\u00f3n entre dispositivos</h2>\n  <div class=\"card\">\n    ${sync.code?`<p class=\"sub\">\u2601 Activa. Tus registros se guardan en la nube y aparecen en cualquier dispositivo donde uses el mismo c\u00f3digo.</p>\n      <div class=\"note\"><b>C\u00f3digo:</b> <span style=\"word-break:break-all\">${esc(sync.code)}</span></div>\n      <p class=\"sub\" id=\"syncMsg\" style=\"margin-top:8px\">${esc(syncLine())}</p>\n      <div class=\"row\" style=\"margin-top:10px\"><button class=\"btn sec sm grow\" id=\"syncNowBtn\">Sincronizar ahora</button><button class=\"btn sec sm grow\" id=\"copyLink\">Copiar enlace</button></div>\n      <button class=\"link\" id=\"syncOff\" style=\"margin-top:8px\">Desactivar en este dispositivo</button>`:\n    `<p class=\"sub\">Escribe el mismo c\u00f3digo en cada dispositivo (celular, computador) para ver los mismos registros.</p>\n      <label class=\"fld\">C\u00f3digo de sincronizaci\u00f3n<input id=\"f_code\" autocomplete=\"off\" autocapitalize=\"none\" spellcheck=\"false\" placeholder=\"m\u00ednimo 8 caracteres\"></label>\n      <div class=\"row\" style=\"margin-top:10px\"><button class=\"btn sm grow\" id=\"syncOn\">Activar</button><button class=\"btn sec sm\" id=\"genCode\">Crear c\u00f3digo</button></div>`}\n    <p class=\"sub\" style=\"margin-top:10px;font-size:12px\">Quien tenga el c\u00f3digo puede ver y cambiar tus registros. Comp\u00e1rtelo solo con quien quieras.</p>\n  </div>\n  <h2>Copia de seguridad</h2>\n  <div class=\"card\">\n    <p class=\"sub\">Tus datos se guardan en este navegador. Si cambias de celular o borras los datos del navegador, exporta antes una copia.</p>\n    <div class=\"row\" style=\"margin-top:10px\"><button class=\"btn sec sm grow\" id=\"exp\">Exportar</button><button class=\"btn sec sm grow\" id=\"imp\">Importar</button></div>\n    <input type=\"file\" id=\"file\" accept=\"application/json\" hidden>\n    <div style=\"margin-top:10px\"><button class=\"btn sec sm\" id=\"wipe\" style=\"color:#b3261e\">Borrar todos mis datos</button></div>\n  </div>\n  <p class=\"sub\" style=\"margin:14px 6px\">Esta rutina es una gu\u00eda general y no reemplaza la valoraci\u00f3n de un profesional de salud. Ante dolor persistente en rodillas o cadera, consulta con un fisioterapeuta.</p>`;\n}\n\n/* ============ SINCRONIZACI\u00d3N ============ */\nconst SKEY=\"chikyGymSync\";\nsync={code:null,last:0,msg:\"\",busy:false,t:null};\ntry{sync.code=localStorage.getItem(SKEY)||null}catch(e){}\nfunction setSyncMsg(m){sync.msg=m;const e=$(\"syncMsg\");if(e)e.textContent=syncLine()}\nfunction syncLine(){\n  const t=sync.last?new Intl.DateTimeFormat(\"es-CO\",{timeZone:TZ,hour:\"2-digit\",minute:\"2-digit\",hourCycle:\"h23\"}).format(new Date(sync.last)):\"\";\n  return (sync.msg||\"\")+(t&&!/^Sincronizando/.test(sync.msg||\"\")?` \u00b7 \u00faltima vez ${t}`:\"\");\n}\nfunction schedulePush(){if(!sync||!sync.code)return;clearTimeout(sync.t);sync.t=setTimeout(()=>syncNow(),2500)}\nasync function syncApi(method,body){\n  const r=await fetch(\"/api/sync\",{method,headers:{\"X-Sync-Code\":sync.code,\"Content-Type\":\"application/json\"},body:body?JSON.stringify(body):undefined,cache:\"no-store\"});\n  if(r.status===401)throw new Error(\"code\");\n  if(!r.ok)throw new Error(\"na\");\n  try{return await r.json()}catch(e){throw new Error(\"na\")}\n}\nfunction syncErr(e){\n  if(e&&e.message===\"code\")return \"El c\u00f3digo no es v\u00e1lido (m\u00ednimo 8 caracteres).\";\n  if(e&&e.message===\"na\")return \"La sincronizaci\u00f3n no est\u00e1 disponible en esta direcci\u00f3n.\";\n  return \"Sin conexi\u00f3n. Se sincronizar\u00e1 cuando vuelva internet.\";\n}\nfunction applyRemote(r){\n  const d=r.data;\n  SYNC_FIELDS.forEach(k=>{if(d[k]!==undefined)state[k]=d[k]});\n  state.profile={...DEF.profile,...state.profile};state.avatar={...DEF.avatar,...state.avatar};\n  state.rev=r.rev;state.week=currentWeek();lastFp=JSON.stringify(snapshot());\n  try{localStorage.setItem(KEY,JSON.stringify(state))}catch(e){}\n}\nfunction safeRender(){const a=document.activeElement;if(!(a&&/INPUT|TEXTAREA|SELECT/.test(a.tagName||\"\")))render()}\nasync function syncNow(){\n  if(!sync.code||sync.busy)return;\n  sync.busy=true;setSyncMsg(\"Sincronizando\u2026\");\n  try{\n    const r=await syncApi(\"GET\"),mine=state.rev||0;\n    if(r.data&&(r.rev||0)>mine){applyRemote(r);sync.last=Date.now();setSyncMsg(\"Datos actualizados desde la nube\");safeRender()}\n    else if(mine>(r.rev||0)){await syncApi(\"PUT\",{rev:mine,data:snapshot()});sync.last=Date.now();setSyncMsg(\"Guardado en la nube\")}\n    else{sync.last=Date.now();setSyncMsg(\"Todo al d\u00eda\")}\n  }catch(e){setSyncMsg(syncErr(e))}\n  sync.busy=false;\n}\nasync function linkCode(code){\n  code=(code||\"\").trim();\n  if(code.length<8)return toast(\"El c\u00f3digo debe tener al menos 8 caracteres\");\n  const prev=sync.code;sync.code=code;\n  try{\n    const r=await syncApi(\"GET\"),mine=state.rev||0;\n    if(r.data){\n      if(!mine||confirm(\"Ya hay datos guardados en la nube con este c\u00f3digo.\\n\\nAceptar: usar los datos de la nube (se reemplazan los de este dispositivo).\\nCancelar: conservar los de este dispositivo y reemplazar los de la nube.\")){applyRemote(r);sync.msg=\"Datos descargados de la nube\"}\n      else{state.rev=Date.now();await syncApi(\"PUT\",{rev:state.rev,data:snapshot()});sync.msg=\"Guardado en la nube\"}\n    }else{state.rev=Date.now();await syncApi(\"PUT\",{rev:state.rev,data:snapshot()});sync.msg=\"Sincronizaci\u00f3n activada\"}\n    try{localStorage.setItem(SKEY,code)}catch(e){}\n    sync.last=Date.now();save();state.view=\"me\";render();toast(\"Sincronizaci\u00f3n activada\");\n  }catch(e){sync.code=prev;toast(syncErr(e))}\n}\nfunction genCode(){\n  const al=\"abcdefghjkmnpqrstuvwxyz23456789\",a=new Uint8Array(12);crypto.getRandomValues(a);\n  const c=[...a].map(x=>al[x%al.length]).join(\"\");return `rosa-${c.slice(0,4)}-${c.slice(4,8)}-${c.slice(8,12)}`;\n}\n(function(){\n  const m=/^#c=(.+)$/.exec(location.hash||\"\");\n  if(m){let c=\"\";try{c=decodeURIComponent(m[1])}catch(e){}\n    try{history.replaceState(null,\"\",location.pathname+location.search)}catch(e){}\n    if(c.length>=8&&c!==sync.code)setTimeout(()=>linkCode(c),400)}\n})();\ndocument.addEventListener(\"visibilitychange\",()=>{if(!document.hidden)syncNow()});\nwindow.addEventListener(\"online\",()=>syncNow());\n\n/* ============ RENDER ============ */\nfunction render(){\n  const y=window.scrollY;\n  $(\"app\").innerHTML={home:viewHome,plan:viewPlan,cal:viewCal,prog:viewProg,me:viewMe}[state.view]();\n  drawNav();bind();window.scrollTo(0,y);\n}\nfunction photoFrom(file){\n  const r=new FileReader();\n  r.onload=()=>{const img=new Image();img.onload=()=>{\n    const s=Math.min(img.width,img.height),c=document.createElement(\"canvas\");c.width=c.height=240;\n    c.getContext(\"2d\").drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,240,240);\n    state.avatar.photo=c.toDataURL(\"image/jpeg\",.82);state.avatar.mode=\"photo\";save();render();toast(\"Foto actualizada\");\n  };img.onerror=()=>toast(\"No se pudo leer la imagen\");img.src=r.result};\n  r.readAsDataURL(file);\n}\nfunction newCycle(){\n  Object.entries(state.log).forEach(([k,date])=>{const [w,d]=k.split(\"-\").map(Number);state.past.push({date,day:d,week:w})});\n  state.done={};state.kg={};state.rest={};state.log={};\n  state.start=mondayOf(bogota().iso);state.week=1;state.day=0;\n}\nfunction bind(){\n  const q=(s,f)=>document.querySelectorAll(s).forEach(f);\n  const on=(id,f)=>{const e=$(id);if(e)e.onclick=f};\n  q(\"[data-v2]\",b=>b.onclick=()=>{state.view=b.dataset.v2;save();render();window.scrollTo(0,0)});\n  q(\"[data-go]\",b=>b.onclick=()=>{state.day=+b.dataset.go;state.week=+b.dataset.gw;state.view=\"plan\";save();render();window.scrollTo(0,0)});\n  q(\"[data-cgo]\",b=>b.onclick=()=>{const [d,w]=b.dataset.cgo.split(\"-\").map(Number);state.day=d;state.week=w;state.view=\"plan\";save();render();window.scrollTo(0,0)});\n  q(\"[data-cm]\",b=>b.onclick=()=>{state.calMonth=addMonth(state.calMonth,+b.dataset.cm);save();render()});\n  q(\"[data-pt]\",b=>b.onclick=()=>{state.progTab=b.dataset.pt;save();render()});\n  q(\"[data-week]\",b=>b.onclick=()=>{state.week=+b.dataset.week;save();render()});\n  q(\"[data-day]\",b=>b.onclick=()=>{state.day=+b.dataset.day;save();render()});\n  q(\"[data-info]\",b=>b.onclick=()=>fichaModal(exInfo(state.day,+b.dataset.info)));\n  q(\"[data-swap]\",b=>b.onclick=()=>swapModal(state.day,+b.dataset.swap));\n  q(\"[data-ficha]\",b=>b.onclick=()=>{const n=b.dataset.ficha,l=lookup(n);fichaModal(l||{name:n,tip:\"Ejercicio registrado en tu historial.\",how:null,group:\"Espalda\",sets:\"\",reps:\"\",rest:0,alt:false})});\n  q(\"[data-set]\",b=>b.onclick=()=>{\n    const i=+b.dataset.set,n=+b.dataset.n,k=kx(state.week,state.day,i),cur=+state.done[k]||0,ex=DAYS[state.day].ex[i];\n    const nv=cur===n?n-1:n;state.done[k]=nv;\n    const iso=bogota().iso;state.cnt[iso]=Math.max(0,(state.cnt[iso]||0)+(nv-cur));\n    syncLog(state.week,state.day);save();render();\n    if(nv>cur&&state.auto){\n      const rs=state.rest[k]??ex[4];\n      if(rs&&nv<setsFor(ex,state.week))startTimer(rs,exInfo(state.day,i).name);\n    }\n  });\n  q(\"[data-kg]\",inp=>inp.onchange=()=>{\n    const i=+inp.dataset.kg,v=inp.value.trim().replace(\",\",\".\");\n    state.kg[kx(state.week,state.day,i)]=v;\n    setHist(exInfo(state.day,i).name,state.week,v);save();\n  });\n  q(\"[data-rest]\",b=>b.onclick=()=>{state.rest[kx(state.week,state.day,+b.dataset.rest)]=+b.dataset.s;save();render()});\n  q(\"[data-mode]\",b=>b.onclick=()=>{state.avatar.mode=b.dataset.mode;save();render()});\n  q(\"[data-av]\",b=>b.onclick=()=>{state.avatar[b.dataset.av]=+b.dataset.i;save();render()});\n  const f=(id,fn)=>{const e=$(id);if(e)e.onclick=fn};\n  const ta=()=>{state.auto=!state.auto;save();render();toast(state.auto?\"Descanso autom\u00e1tico activado\":\"Descanso autom\u00e1tico desactivado\")};\n  f(\"autoT\",ta);f(\"autoT2\",ta);\n  f(\"resetDay\",()=>{if(confirm(\"\u00bfReiniciar las series marcadas de este d\u00eda y semana?\")){\n    DAYS[state.day].ex.forEach((_,i)=>delete state.done[kx(state.week,state.day,i)]);\n    delete state.log[`${state.week}-${state.day}`];save();render()}});\n  f(\"addBody\",()=>{\n    const v=parseFloat(($(\"bkg\").value||\"\").replace(\",\",\".\"));\n    if(!(v>25&&v<250)){$(\"bkg\").focus();toast(\"Escribe un peso v\u00e1lido en kg\");return}\n    const iso=bogota().iso;state.body=state.body.filter(b=>b.date!==iso);state.body.push({date:iso,kg:Math.round(v*10)/10});save();render();toast(\"Peso guardado\");\n  });\n  f(\"pickPhoto\",()=>$(\"photo\").click());\n  const ph=$(\"photo\");if(ph)ph.onchange=()=>{if(ph.files[0])photoFrom(ph.files[0])};\n  f(\"saveProfile\",()=>{\n    const age=parseInt($(\"f_age\").value,10),cm=parseInt($(\"f_cm\").value,10),kg=parseFloat(($(\"f_kg\").value||\"\").replace(\",\",\".\"));\n    if(!(age>=12&&age<=100))return toast(\"Revisa la edad\");\n    if(!(cm>=120&&cm<=220))return toast(\"Revisa la estatura (en cm)\");\n    if(!(kg>25&&kg<250))return toast(\"Revisa el peso (en kg)\");\n    Object.assign(state.profile,{name:$(\"f_name\").value.trim()||\"Chiky\",age,cm,goal:$(\"f_goal\").value.trim(),level:$(\"f_level\").value,limits:$(\"f_limits\").value.trim(),material:$(\"f_mat\").value.trim()});\n    if(kg!==lastBody()){const iso=bogota().iso;state.body=state.body.filter(b=>b.date!==iso);state.body.push({date:iso,kg:Math.round(kg*10)/10})}\n    save();render();toast(\"Datos guardados\");\n  });\n  f(\"restart\",()=>{if(confirm(\"\u00bfEmpezar un nuevo ciclo de 4 semanas desde esta semana? Se limpian las series y pesos del ciclo actual, pero se conservan tu historial, calendario y peso corporal.\")){newCycle();save();render();toast(\"Nuevo ciclo iniciado\")}});\n  f(\"syncOn\",()=>linkCode($(\"f_code\").value));\n  f(\"genCode\",()=>{$(\"f_code\").value=genCode()});\n  f(\"syncNowBtn\",()=>syncNow());\n  f(\"syncOff\",()=>{if(confirm(\"\u00bfDesactivar la sincronizaci\u00f3n en este dispositivo? Los datos en la nube no se borran.\")){sync.code=null;try{localStorage.removeItem(SKEY)}catch(e){}render();toast(\"Sincronizaci\u00f3n desactivada\")}});\n  f(\"copyLink\",()=>{\n    const link=`${location.origin}${location.pathname}#c=${encodeURIComponent(sync.code)}`;\n    if(navigator.clipboard&&navigator.clipboard.writeText)navigator.clipboard.writeText(link).then(()=>toast(\"Enlace copiado\"),()=>prompt(\"Copia este enlace:\",link));\n    else prompt(\"Copia este enlace:\",link);\n  });\n  f(\"clearSwap\",()=>{state.swap={};save();render();toast(\"Ejercicios originales restaurados\")});\n  f(\"exp\",()=>{\n    const blob=new Blob([JSON.stringify(state,null,1)],{type:\"application/json\"});\n    const a=document.createElement(\"a\");a.href=URL.createObjectURL(blob);a.download=`chiky-gym-${bogota().iso}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);\n  });\n  f(\"imp\",()=>$(\"file\").click());\n  const fi=$(\"file\");if(fi)fi.onchange=()=>{\n    const r=new FileReader();r.onload=()=>{try{const o=JSON.parse(r.result);if(typeof o!==\"object\"||!o.done)throw 0;\n      state={...state,...o,profile:{...state.profile,...(o.profile||{})},avatar:{...state.avatar,...(o.avatar||{})},view:\"me\"};save();render();toast(\"Copia importada\")}catch(e){toast(\"El archivo no es una copia v\u00e1lida de Chiky Gym\")}};\n    if(fi.files[0])r.readAsText(fi.files[0]);\n  };\n  f(\"wipe\",()=>{if(confirm(\"\u00bfBorrar todo tu registro en este dispositivo? Esto tambi\u00e9n desactiva la sincronizaci\u00f3n aqu\u00ed; la copia en la nube no se borra. No se puede deshacer.\")){try{localStorage.removeItem(KEY);localStorage.removeItem(SKEY)}catch(e){}location.reload()}});\n}\n\nsetInterval(()=>{const h=$(\"hm\");if(h){const n=bogota();h.textContent=n.time;$(\"dt\").textContent=n.date}},1000);\ndrawTimer();render();\n</script>\n</body>\n</html>\n";

const enc = new TextEncoder();
async function keyFor(code) {
  const h = await crypto.subtle.digest("SHA-256", enc.encode("chiky:" + code));
  return "u:" + [...new Uint8Array(h)].map(b => b.toString(16).padStart(2, "0")).join("");
}
const json = (o, status = 200) => new Response(JSON.stringify(o), {
  status,
  headers: { "content-type": "application/json; charset=utf-8", "cache-control": "no-store", "x-content-type-options": "nosniff" }
});

export default {
  async fetch(req, env) {
    const url = new URL(req.url);

    if (url.pathname === "/api/sync") {
      if (!env.SYNC) return json({ error: "KV no configurado" }, 500);
      const code = req.headers.get("X-Sync-Code") || "";
      if (code.length < 8 || code.length > 100) return json({ error: "código inválido" }, 401);
      const key = await keyFor(code);

      if (req.method === "GET") {
        const v = await env.SYNC.get(key);
        return json(v ? JSON.parse(v) : { rev: 0, data: null });
      }
      if (req.method === "PUT") {
        const text = await req.text();
        if (text.length > 700000) return json({ error: "demasiado grande" }, 413);
        let b;
        try { b = JSON.parse(text); } catch { return json({ error: "json inválido" }, 400); }
        if (typeof b.rev !== "number" || !b.data || typeof b.data !== "object") return json({ error: "formato inválido" }, 400);
        const cur = await env.SYNC.get(key);
        if (cur) { try { if (JSON.parse(cur).rev > b.rev) return json({ ok: false, stale: true }); } catch {} }
        await env.SYNC.put(key, JSON.stringify({ rev: b.rev, data: b.data }));
        return json({ ok: true });
      }
      return json({ error: "método no permitido" }, 405);
    }

    if (url.pathname === "/" || url.pathname === "/index.html") {
      return new Response(HTML, {
        headers: {
          "content-type": "text/html; charset=utf-8",
          "cache-control": "no-cache",
          "referrer-policy": "no-referrer",
          "x-content-type-options": "nosniff"
        }
      });
    }
    return new Response("No encontrado", { status: 404 });
  }
};
